fn asmImmediate(self: *CodeGen, tag: Mir.Inst.FixedTag, imm: Immediate) !void {
    _ = try self.addInst(.{
        .tag = tag[1],
        .ops = switch (imm) {
            .signed => .i_s,
            .unsigned => .i_u,
            .nav => .nav,
            .uav => .uav,
            .lazy_sym => .lazy_sym,
            .extern_func => .extern_func,
        },
        .data = switch (imm) {
            .signed, .unsigned => .{ .i = .{
                .fixes = tag[0],
                .i = switch (imm) {
                    .signed => |s| @bitCast(s),
                    .unsigned => |u| @intCast(u),
                    .nav, .uav, .lazy_sym, .extern_func => unreachable,
                },
            } },
            .nav => |nav| switch (tag[0]) {
                ._ => .{ .nav = nav },
                else => unreachable,
            },
            .uav => |uav| switch (tag[0]) {
                ._ => .{ .uav = uav },
                else => unreachable,
            },
            .lazy_sym => |lazy_sym| switch (tag[0]) {
                ._ => .{ .lazy_sym = lazy_sym },
                else => unreachable,
            },
            .extern_func => |extern_func| switch (tag[0]) {
                ._ => .{ .extern_func = extern_func },
                else => unreachable,
            },
        },
    });
}

