    fn finish(
        temp: Temp,
        inst: Air.Inst.Index,
        op_refs: []const Air.Inst.Ref,
        op_temps: []const Temp,
        cg: *CodeGen,
    ) InnerError!void {
        const tomb_bits = cg.liveness.getTombBits(inst);
        for (0.., op_refs, op_temps) |op_index, op_ref, op_temp| {
            if (op_temp.index == temp.index) continue;
            if (op_temp.tracking(cg).short != .dead) try op_temp.die(cg);
            if (tomb_bits & @as(Air.Liveness.Bpi, 1) << @intCast(op_index) == 0) continue;
            if (cg.reused_operands.isSet(op_index)) continue;
            try cg.processDeath(op_ref.toIndexAllowNone() orelse continue, .{});
        }
        if (cg.liveness.isUnused(inst)) try temp.die(cg) else {
            switch (temp.unwrap(cg)) {
                .ref, .err_ret_trace => {
                    const temp_mcv = temp.tracking(cg).short;
                    const result = result: switch (temp_mcv) {
                        .none,
                        .unreach,
                        .dead,
                        .indirect_load_frame,
                        .elementwise_args,
                        .reserved_frame,
                        .air_ref,
                        => unreachable,
                        .undef, .immediate, .lea_frame => temp_mcv,
                        .eflags,
                        .register,
                        .register_pair,
                        .register_triple,
                        .register_quadruple,
                        .register_offset,
                        .register_overflow,
                        .register_mask,
                        .memory,
                        .indirect,
                        .load_frame,
                        .load_nav,
                        .lea_nav,
                        .load_uav,
                        .lea_uav,
                        .load_lazy_sym,
                        .lea_lazy_sym,
                        .load_extern_func,
                        .lea_extern_func,
                        => {
                            const result = try cg.allocRegOrMem(inst, true);
                            try cg.genCopy(cg.typeOfIndex(inst), result, temp_mcv, .{});
                            break :result result;
                        },
                    };
                    tracking_log.debug("{f} => {f} (birth)", .{ inst, result });
                    cg.inst_tracking.putAssumeCapacityNoClobber(inst, .init(result));
                },
                .temp => |temp_index| {
                    const temp_tracking = temp_index.tracking(cg);
                    tracking_log.debug("{f} => {f} (birth)", .{ inst, temp_tracking.short });
                    cg.inst_tracking.putAssumeCapacityNoClobber(inst, .init(temp_tracking.short));
                    assert(cg.reuseTemp(inst, temp_index.toIndex(), temp_tracking));
                },
            }
        }
        for (0.., op_refs, op_temps) |op_index, op_ref, op_temp| {
            if (op_temp.index != temp.index) continue;
            if (tomb_bits & @as(Air.Liveness.Bpi, 1) << @intCast(op_index) == 0) continue;
            if (cg.reused_operands.isSet(op_index)) continue;
            try cg.processDeath(op_ref.toIndexAllowNone() orelse continue, .{});
        }
    }

    fn die(temp: Temp, cg: *CodeGen) InnerError!void {
        switch (temp.unwrap(cg)) {
            .ref, .err_ret_trace => {},
            .temp => |temp_index| try temp_index.tracking(cg).die(cg, temp_index.toIndex(), .{}),
        }
    }

    const Index = enum(u5) {
        _,

        fn toIndex(index: Index) Air.Inst.Index {
            return .fromTargetIndex(@intFromEnum(index));
        }

        fn fromIndex(index: Air.Inst.Index) Index {
            return @enumFromInt(index.toTargetIndex());
        }

        fn tracking(index: Index, cg: *CodeGen) *InstTracking {
            return &cg.inst_tracking.values()[@intFromEnum(index)];
        }

        fn isValid(index: Index, cg: *CodeGen) bool {
            return @intFromEnum(index) < @intFromEnum(cg.next_temp_index) and
                index.tracking(cg).short != .dead;
        }

        fn typeOf(index: Index, cg: *CodeGen) Type {
            assert(index.isValid(cg));
            return cg.temp_type[@intFromEnum(index)];
        }

        const max = std.math.maxInt(@typeInfo(Index).@"enum".tag_type);
        const Set = std.StaticBitSet(max);
        const SafetySet = if (std.debug.runtime_safety) Set else struct {
            inline fn initEmpty() @This() {
                return .{};
            }

            inline fn isSet(_: @This(), index: usize) bool {
                assert(index < max);
                return true;
            }

            inline fn set(_: @This(), index: usize) void {
                assert(index < max);
            }

            inline fn eql(_: @This(), _: @This()) bool {
                return true;
            }
        };
    };
};

fn resetTemps(cg: *CodeGen, from_index: Temp.Index) InnerError!void {
    var any_valid = false;
    for (@intFromEnum(from_index)..@intFromEnum(cg.next_temp_index)) |temp_index| {
        const temp: Temp.Index = @enumFromInt(temp_index);
        if (temp.isValid(cg)) {
            any_valid = true;
            tracking_log.err("failed to kill {f}: {f}", .{
                temp.toIndex(),
                cg.temp_type[temp_index].fmt(cg.pt),
            });
        }
        cg.temp_type[temp_index] = undefined;
    }
    if (any_valid) return cg.fail("failed to kill all temps", .{});
    cg.next_temp_index = from_index;
}

fn reuseTemp(
    cg: *CodeGen,
    new_inst: Air.Inst.Index,
    old_inst: Air.Inst.Index,
    tracking: *InstTracking,
) bool {
    switch (tracking.short) {
        .register,
        .register_pair,
        .register_offset,
        .register_overflow,
        .register_mask,
        .indirect,
        => for (tracking.short.getRegs()) |tracked_reg| {
            if (RegisterManager.indexOfRegIntoTracked(tracked_reg)) |tracked_index| {
                cg.register_manager.registers[tracked_index] = new_inst;
            }
        },
        .load_frame => |frame_addr| if (frame_addr.index.isNamed()) return false,
        else => {},
    }
    switch (tracking.short) {
        .eflags, .register_overflow => cg.eflags_inst = new_inst,
        else => {},
    }
    tracking.reuse(cg, new_inst, old_inst);
    return true;
}

fn tempAlloc(cg: *CodeGen, ty: Type) InnerError!Temp {
    const temp_index = cg.next_temp_index;
    temp_index.tracking(cg).* = .init(
        try cg.allocRegOrMemAdvanced(ty, temp_index.toIndex(), true),
    );
    cg.temp_type[@intFromEnum(temp_index)] = ty;
    cg.next_temp_index = @enumFromInt(@intFromEnum(temp_index) + 1);
    return .{ .index = temp_index.toIndex() };
}

fn tempAllocReg(cg: *CodeGen, ty: Type, rs: RegisterManager.RegisterBitSet) InnerError!Temp {
    const temp_index = cg.next_temp_index;
    temp_index.tracking(cg).* = .init(
        .{ .register = try cg.register_manager.allocReg(temp_index.toIndex(), rs) },
    );
    cg.temp_type[@intFromEnum(temp_index)] = ty;
    cg.next_temp_index = @enumFromInt(@intFromEnum(temp_index) + 1);
    return .{ .index = temp_index.toIndex() };
}

fn tempAllocRegPair(cg: *CodeGen, ty: Type, rs: RegisterManager.RegisterBitSet) InnerError!Temp {
    const temp_index = cg.next_temp_index;
    temp_index.tracking(cg).* = .init(
        .{ .register_pair = try cg.register_manager.allocRegs(2, @splat(temp_index.toIndex()), rs) },
    );
    cg.temp_type[@intFromEnum(temp_index)] = ty;
    cg.next_temp_index = @enumFromInt(@intFromEnum(temp_index) + 1);
    return .{ .index = temp_index.toIndex() };
}

fn tempAllocMem(cg: *CodeGen, ty: Type) InnerError!Temp {
    const temp_index = cg.next_temp_index;
    temp_index.tracking(cg).* = .init(
        try cg.allocRegOrMemAdvanced(ty, temp_index.toIndex(), false),
    );
    cg.temp_type[@intFromEnum(temp_index)] = ty;
    cg.next_temp_index = @enumFromInt(@intFromEnum(temp_index) + 1);
    return .{ .index = temp_index.toIndex() };
}

fn tempInit(cg: *CodeGen, ty: Type, value: MCValue) InnerError!Temp {
    const temp_index = cg.next_temp_index;
    temp_index.tracking(cg).* = .init(value);
    cg.temp_type[@intFromEnum(temp_index)] = ty;
    try cg.getValue(value, temp_index.toIndex());
    cg.next_temp_index = @enumFromInt(@intFromEnum(temp_index) + 1);
    return .{ .index = temp_index.toIndex() };
}

fn tempFromValue(cg: *CodeGen, value: Value) InnerError!Temp {
    return cg.tempInit(value.typeOf(cg.pt.zcu), try cg.lowerValue(value));
}

fn tempMemFromValue(cg: *CodeGen, value: Value) InnerError!Temp {
    return cg.tempMemFromAlignedValue(.none, value);
}

fn tempMemFromAlignedValue(cg: *CodeGen, alignment: InternPool.Alignment, value: Value) InnerError!Temp {
    const ty = value.typeOf(cg.pt.zcu);
    return cg.tempInit(ty, .{ .load_uav = .{
        .val = value.toIntern(),
        .orig_ty = (try cg.pt.ptrType(.{
            .child = ty.toIntern(),
            .flags = .{
                .is_const = true,
                .alignment = alignment,
            },
        })).toIntern(),
    } });
}

fn tempFromOperand(cg: *CodeGen, op_ref: Air.Inst.Ref, op_dies: bool) InnerError!Temp {
    if (op_dies) {
        const temp_index = cg.next_temp_index;
        const temp: Temp = .{ .index = temp_index.toIndex() };
        const op_inst = op_ref.toIndex().?;
        const tracking = cg.getResolvedInstValue(op_inst);
        temp_index.tracking(cg).* = tracking.*;
        if (!cg.reuseTemp(temp.index, op_inst, tracking)) return .{ .index = op_ref.toIndex().? };
        cg.temp_type[@intFromEnum(temp_index)] = cg.typeOf(op_ref);
        cg.next_temp_index = @enumFromInt(@intFromEnum(temp_index) + 1);
        return temp;
    }

    if (op_ref.toIndex()) |op_inst| return .{ .index = op_inst };
    return cg.tempFromValue(.fromInterned(op_ref.toInterned().?));
}

fn tempsFromOperandsInner(
    cg: *CodeGen,
    inst: Air.Inst.Index,
    op_temps: []Temp,
    op_refs: []const Air.Inst.Ref,
) InnerError!void {
    for (op_temps, 0.., op_refs) |*op_temp, op_index, op_ref| op_temp.* = try cg.tempFromOperand(op_ref, for (op_refs[0..op_index]) |prev_op_ref| {
        if (op_ref == prev_op_ref) break false;
    } else cg.liveness.operandDies(inst, @intCast(op_index)));
}

inline fn tempsFromOperands(
    cg: *CodeGen,
    inst: Air.Inst.Index,
    op_refs: anytype,
) InnerError![op_refs.len]Temp {
    var op_temps: [op_refs.len]Temp = undefined;
    try cg.tempsFromOperandsInner(inst, &op_temps, &op_refs);
    return op_temps;
}

const Operand = union(enum) {
    none,
    reg: Register,
    mem: Memory,
    imm: Immediate,
    inst: Mir.Inst.Index,
};

const Select = struct {
    cg: *CodeGen,
    types: [@intFromEnum(Select.Operand.Ref.none)]Type,
    temps: [@intFromEnum(Select.Operand.Ref.none)]Temp,
    labels: [@intFromEnum(Label._)]struct {
        backward: ?Mir.Inst.Index,
        forward: [3]?Mir.Inst.Index,
    },
    top: u3,

    const Error = InnerError || error{SelectFailed};

    fn emitLabel(s: *Select, label_index: Label) void {
        assert(@intFromEnum(label_index) < @intFromEnum(Label._));
        const label = &s.labels[@intFromEnum(label_index)];
        for (&label.forward) |*reloc| {
            if (reloc.*) |r| s.cg.performReloc(r);
            reloc.* = null;
        }
        label.backward = @intCast(s.cg.mir_instructions.len);
    }

    fn emit(s: *Select, inst: Instruction) InnerError!void {
        const mir_tag: Mir.Inst.FixedTag = .{ inst[1], inst[2] };
        pseudo: {
            switch (inst[0]) {
                .@"0:", .@"1:", .@"2:", .@"3:", .@"4:" => |label| s.emitLabel(label),
                ._ => {},
                .pseudo => break :pseudo,
            }
            var mir_ops: [4]CodeGen.Operand = undefined;
            inline for (&mir_ops, 3..) |*mir_op, inst_index| mir_op.* = try inst[inst_index].lower(s);
            s.cg.asmOps(mir_tag, mir_ops) catch |err| switch (err) {
                error.InvalidInstruction => {
                    const fixes = @tagName(mir_tag[0]);
                    const fixes_blank = std.mem.indexOfScalar(u8, fixes, '_').?;
                    return s.cg.fail("invalid instruction: '{s}{s}{s} {s} {s} {s} {s}'", .{
                        fixes[0..fixes_blank],
                        @tagName(mir_tag[1]),
                        fixes[fixes_blank + 1 ..],
                        @tagName(mir_ops[0]),
                        @tagName(mir_ops[1]),
                        @tagName(mir_ops[2]),
                        @tagName(mir_ops[3]),
                    });
                },
                else => |e| return e,
            };
        }
        switch (mir_tag[0]) {
            .f_ => switch (mir_tag[1]) {
                .@"2xm1",
                .abs,
                .add,
                .chs,
                .clex,
                .com,
                .comi,
                .cos,
                .div,
                .divr,
                .free,
                .mul,
                .nop,
                .prem,
                .rndint,
                .scale,
                .sin,
                .sqrt,
                .st,
                .sub,
                .subr,
                .tst,
                .ucom,
                .ucomi,
                .wait,
                .xam,
                .xch,
                => {},
                .init, .save => s.top = 0,
                .ld, .ptan, .sincos, .xtract => s.top -%= 1,
                .patan, .yl2x => s.top +%= 1,
                .rstor => unreachable,
                else => unreachable,
            },
            .f_1 => switch (mir_tag[1]) {
                .ld => s.top -%= 1,
                .prem => {},
                else => unreachable,
            },
            .f_b, .f_be, .f_e, .f_nb, .f_nbe, .f_ne, .f_nu, .f_u => switch (mir_tag[1]) {
                .cmov => {},
                else => unreachable,
            },
            .f_cw, .f_env, .f_sw => switch (mir_tag[1]) {
                .ld, .st => {},
                else => unreachable,
            },
            .f_p1 => switch (mir_tag[1]) {
                .yl2x => s.top +%= 1,
                else => unreachable,
            },
            .f_cstp => switch (mir_tag[1]) {
                .de => s.top -%= 1,
                .in => s.top +%= 1,
                else => unreachable,
            },
            .f_l2e, .f_l2t, .f_lg2, .f_ln2, .f_pi, .f_z => switch (mir_tag[1]) {
                .ld => s.top -%= 1,
                else => unreachable,
            },
            .f_p => switch (mir_tag[1]) {
                .add, .com, .comi, .div, .divr, .mul, .st, .sub, .subr, .ucom, .ucomi => s.top +%= 1,
                else => {
                    const fixes = @tagName(mir_tag[0]);
                    const fixes_blank = std.mem.indexOfScalar(u8, fixes, '_').?;
                    std.debug.panic("{s}: {s}{s}{s}\n", .{
                        @src().fn_name,
                        fixes[0..fixes_blank],
                        @tagName(mir_tag[1]),
                        fixes[fixes_blank + 1 ..],
                    });
                },
            },
            .f_pp => switch (mir_tag[1]) {
                .com, .ucom => s.top +%= 2,
                else => unreachable,
            },
            .fb_ => switch (mir_tag[1]) {
                .ld => s.top -%= 1,
                else => unreachable,
            },
            .fb_p => switch (mir_tag[1]) {
                .st => s.top +%= 1,
                else => unreachable,
            },
            .fi_ => switch (mir_tag[1]) {
                .add, .com, .div, .divr, .mul, .st, .stt, .sub, .subr => {},
                .ld => s.top -%= 1,
                else => unreachable,
            },
            .fi_p => switch (mir_tag[1]) {
                .com, .st, .stt => s.top +%= 1,
                else => unreachable,
            },
            .fn_ => switch (mir_tag[1]) {
                .clex => {},
                .init, .save => s.top = 0,
                else => unreachable,
            },
            .fn_cw, .fn_env, .fn_sw => switch (mir_tag[1]) {
                .st => {},
                else => unreachable,
            },
            .fx_ => switch (mir_tag[1]) {
                .rstor => unreachable,
                .save => {},
                else => unreachable,
            },
            else => {},
        }
    }

    fn lowerReg(s: *const Select, reg: Register) Register {
        return if (reg.isClass(.x87)) @enumFromInt(@intFromEnum(Register.st0) + (@as(u3, @intCast(reg.enc())) -% s.top)) else reg;
    }

    const Case = struct {
        required_abi: enum { any, gnu, msvc } = .any,
        required_cc_abi: enum { any, sysv64, win64 } = .any,
        required_features: [4]?std.Target.x86.Feature = @splat(null),
        src_constraints: [@intFromEnum(Select.Operand.Ref.none) - @intFromEnum(Select.Operand.Ref.src0)]Constraint = @splat(.any),
        dst_constraints: [@intFromEnum(Select.Operand.Ref.src0) - @intFromEnum(Select.Operand.Ref.dst0)]Constraint = @splat(.any),
        patterns: []const Select.Pattern,
        call_frame: packed struct(u16) { size: u10 = 0, alignment: InternPool.Alignment } = .{ .size = 0, .alignment = .none },
        extra_temps: [@intFromEnum(Select.Operand.Ref.dst0) - @intFromEnum(Select.Operand.Ref.tmp0)]TempSpec = @splat(.unused),
        dst_temps: [@intFromEnum(Select.Operand.Ref.src0) - @intFromEnum(Select.Operand.Ref.dst0)]TempSpec.Kind = @splat(.unused),
        clobbers: packed struct {
            eflags: bool = false,
            caller_preserved: CallConv = .none,
        } = .{},
        each: union(enum) {
            once: []const Instruction,
        },

        const CallConv = enum(u2) { none, ccc, zigcc };
    };

    const Constraint = union(enum) {
        any,
        any_bool_vec,
        any_int,
        any_signed_int,
        any_unsigned_int,
        any_scalar_int,
        any_scalar_signed_int,
        any_scalar_unsigned_int,
        any_signed_int_or_full_vec,
        any_float,
        po2_any,
        bool,
        bool_vec: Memory.Size,
        exact_bool_vec: u16,
        ptr_any_bool_vec,
        ptr_bool_vec: Memory.Size,
        ptr_any_bool_vec_elem,
        ptr_bool_vec_elem: Memory.Size,
        remainder_bool_vec: OfIsSizes,
        exact_remainder_bool_vec: struct { of: Memory.Size, is: u16 },
        signed_int_vec: Memory.Size,
        signed_int_or_full_vec: Memory.Size,
        unsigned_int_vec: Memory.Size,
        size: Memory.Size,
        multiple_size: Memory.Size,
        int: Memory.Size,
        int_or_float: Memory.Size,
        scalar_int_is: Memory.Size,
        scalar_signed_int_is: Memory.Size,
        scalar_unsigned_int_is: Memory.Size,
        scalar: OfIsSizes,
        scalar_int: OfIsSizes,
        scalar_signed_int: OfIsSizes,
        scalar_unsigned_int: OfIsSizes,
        exclusive_scalar_int: OfIsSizes,
        exclusive_scalar_signed_int: OfIsSizes,
        exclusive_scalar_unsigned_int: OfIsSizes,
        exact_scalar_int: OfIsSizes,
        exact_scalar_signed_int: OfIsSizes,
        exact_scalar_unsigned_int: OfIsSizes,
        scalar_signed_or_exclusive_int: OfIsSizes,
        scalar_exact_int: struct { of: Memory.Size, is: u16 },
        scalar_exact_signed_int: struct { of: Memory.Size, is: u16 },
        scalar_exact_unsigned_int: struct { of: Memory.Size, is: u16 },
        multiple_scalar: OfIsSizes,
        multiple_scalar_int: OfIsSizes,
        unaligned_multiple_scalar_int: OfIsSizes,
        unaligned_multiple_scalar_signed_int: OfIsSizes,
        unaligned_multiple_scalar_unsigned_int: OfIsSizes,
        multiple_scalar_signed_int: OfIsSizes,
        multiple_scalar_unsigned_int: OfIsSizes,
        multiple_scalar_signed_or_exclusive_int: OfIsSizes,
        multiple_scalar_exact_int: struct { of: Memory.Size, is: u16 },
        multiple_scalar_exact_signed_int: struct { of: Memory.Size, is: u16 },
        multiple_scalar_exact_unsigned_int: struct { of: Memory.Size, is: u16 },
        scalar_remainder_int: OfIsSizes,
        scalar_remainder_signed_int: OfIsSizes,
        scalar_remainder_unsigned_int: OfIsSizes,
        scalar_exact_remainder_int: OfIsSizes,
        scalar_exact_remainder_signed_int: OfIsSizes,
        scalar_exact_remainder_unsigned_int: OfIsSizes,
        float: Memory.Size,
        scalar_any_float: Memory.Size,
        scalar_float: OfIsSizes,
        exclusive_scalar_float: OfIsSizes,
        exact_scalar_float: OfIsSizes,
        multiple_scalar_any_float: Memory.Size,
        multiple_scalar_float: OfIsSizes,
        unaligned_multiple_scalar_float: OfIsSizes,
        exact_int: u16,
        exact_signed_int: u16,
        exact_unsigned_int: u16,
        signed_or_exact_int: Memory.Size,
        unsigned_or_exact_int: Memory.Size,
        signed_or_exclusive_int: Memory.Size,
        po2_int: Memory.Size,
        signed_po2_int: Memory.Size,
        unsigned_po2_or_exact_int: Memory.Size,
        remainder_int: OfIsSizes,
        remainder_signed_int: OfIsSizes,
        remainder_unsigned_int: OfIsSizes,
        exact_remainder_int: struct { of: Memory.Size, is: u16 },
        exact_remainder_signed_int: struct { of: Memory.Size, is: u16 },
        exact_remainder_unsigned_int: struct { of: Memory.Size, is: u16 },
        signed_or_exact_remainder_int: OfIsSizes,
        unsigned_or_exact_remainder_int: OfIsSizes,
        signed_int: Memory.Size,
        unsigned_int: Memory.Size,
        elem_size_is: u8,
        po2_elem_size,
        elem_int: Memory.Size,

        const OfIsSizes = struct { of: Memory.Size, is: Memory.Size };

        fn accepts(constraint: Constraint, ty: Type, cg: *CodeGen) bool {
            const zcu = cg.pt.zcu;
            return switch (constraint) {
                .any => true,
                .any_bool_vec => ty.isVector(zcu) and ty.childType(zcu).toIntern() == .bool_type,
                .any_int => cg.intInfo(ty) != null,
                .any_signed_int => if (cg.intInfo(ty)) |int_info| int_info.signedness == .signed else false,
                .any_unsigned_int => if (cg.intInfo(ty)) |int_info| int_info.signedness == .unsigned else false,
                .any_scalar_int => cg.intInfo(ty.scalarType(zcu)) != null,
                .any_scalar_signed_int => if (cg.intInfo(ty.scalarType(zcu))) |int_info| int_info.signedness == .signed else false,
                .any_scalar_unsigned_int => if (cg.intInfo(ty.scalarType(zcu))) |int_info| int_info.signedness == .unsigned else false,
                .any_signed_int_or_full_vec => ty.isVector(zcu) and
                    if (cg.intInfo(ty.childType(zcu))) |int_info| switch (int_info.signedness) {
                        .signed => true,
                        .unsigned => (int_info.bits >= 8 and std.math.isPowerOfTwo(int_info.bits)) or int_info.bits % 128 == 0,
                    } else false,
                .any_float => ty.isRuntimeFloat(),
                .po2_any => std.math.isPowerOfTwo(ty.abiSize(zcu)),
                .bool => ty.toIntern() == .bool_type,
                .bool_vec => |size| ty.isVector(zcu) and ty.scalarType(zcu).toIntern() == .bool_type and
                    size.bitSize(cg.target) >= ty.vectorLen(zcu),
                .exact_bool_vec => |size| ty.isVector(zcu) and ty.scalarType(zcu).toIntern() == .bool_type and
                    size == ty.vectorLen(zcu),
                .ptr_any_bool_vec => switch (zcu.intern_pool.indexToKey(ty.childType(zcu).toIntern())) {
                    .vector_type => |vector_type| vector_type.child == .bool_type,
                    else => false,
                },
                .ptr_bool_vec => |size| switch (zcu.intern_pool.indexToKey(ty.childType(zcu).toIntern())) {
                    .vector_type => |vector_type| vector_type.child == .bool_type and size.bitSize(cg.target) >= vector_type.len,
                    else => false,
                },
                .ptr_any_bool_vec_elem => {
                    const ptr_info = ty.ptrInfo(zcu);
                    return switch (ptr_info.flags.vector_index) {
                        .none => false,
                        else => ptr_info.child == .bool_type,
                    };
                },
                .ptr_bool_vec_elem => |size| {
                    const ptr_info = ty.ptrInfo(zcu);
                    return switch (ptr_info.flags.vector_index) {
                        .none => false,
                        else => ptr_info.child == .bool_type and size.bitSize(cg.target) >= ptr_info.packed_offset.host_size,
                    };
                },
                .remainder_bool_vec => |of_is| ty.isVector(zcu) and ty.scalarType(zcu).toIntern() == .bool_type and
                    of_is.is.bitSize(cg.target) >= (ty.vectorLen(zcu) - 1) % of_is.of.bitSize(cg.target) + 1,
                .exact_remainder_bool_vec => |of_is| ty.isVector(zcu) and ty.scalarType(zcu).toIntern() == .bool_type and
                    of_is.is == (ty.vectorLen(zcu) - 1) % of_is.of.bitSize(cg.target) + 1,
                .signed_int_vec => |size| ty.isVector(zcu) and @divExact(size.bitSize(cg.target), 8) >= ty.abiSize(zcu) and
                    if (cg.intInfo(ty.childType(zcu))) |int_info| int_info.signedness == .signed else false,
                .signed_int_or_full_vec => |size| ty.isVector(zcu) and @divExact(size.bitSize(cg.target), 8) >= ty.abiSize(zcu) and
                    if (cg.intInfo(ty.childType(zcu))) |int_info| switch (int_info.signedness) {
                        .signed => true,
                        .unsigned => (int_info.bits >= 8 and std.math.isPowerOfTwo(int_info.bits)) or int_info.bits % 128 == 0,
                    } else false,
                .unsigned_int_vec => |size| ty.isVector(zcu) and @divExact(size.bitSize(cg.target), 8) >= ty.abiSize(zcu) and
                    if (cg.intInfo(ty.childType(zcu))) |int_info| int_info.signedness == .unsigned else false,
                .size => |size| @divExact(size.bitSize(cg.target), 8) >= ty.abiSize(zcu),
                .multiple_size => |size| ty.abiSize(zcu) % @divExact(size.bitSize(cg.target), 8) == 0,
                .int => |size| if (cg.intInfo(ty)) |int_info| size.bitSize(cg.target) >= int_info.bits else false,
                .int_or_float => |size| if (cg.intInfo(ty)) |int_info|
                    size.bitSize(cg.target) >= int_info.bits
                else if (cg.floatBits(ty)) |float_bits|
                    size.bitSize(cg.target) == float_bits
                else
                    false,
                .scalar_int_is => |size| if (cg.intInfo(ty.scalarType(zcu))) |int_info|
                    size.bitSize(cg.target) >= int_info.bits
                else
                    false,
                .scalar_signed_int_is => |size| if (cg.intInfo(ty.scalarType(zcu))) |int_info| switch (int_info.signedness) {
                    .signed => size.bitSize(cg.target) >= int_info.bits,
                    .unsigned => false,
                } else false,
                .scalar_unsigned_int_is => |size| if (cg.intInfo(ty.scalarType(zcu))) |int_info| switch (int_info.signedness) {
                    .signed => false,
                    .unsigned => size.bitSize(cg.target) >= int_info.bits,
                } else false,
                .scalar => |of_is| @divExact(of_is.of.bitSize(cg.target), 8) >= cg.unalignedSize(ty) and
                    if (cg.intInfo(ty.scalarType(zcu))) |int_info|
                        of_is.is.bitSize(cg.target) >= int_info.bits
                    else if (cg.floatBits(ty.scalarType(zcu))) |float_bits|
                        of_is.is.bitSize(cg.target) == float_bits
                    else
                        false,
                .scalar_int => |of_is| @divExact(of_is.of.bitSize(cg.target), 8) >= cg.unalignedSize(ty) and
                    if (cg.intInfo(ty.scalarType(zcu))) |int_info| of_is.is.bitSize(cg.target) >= int_info.bits else false,
                .scalar_signed_int => |of_is| @divExact(of_is.of.bitSize(cg.target), 8) >= cg.unalignedSize(ty) and
                    if (cg.intInfo(ty.scalarType(zcu))) |int_info| int_info.signedness == .signed and
                        of_is.is.bitSize(cg.target) >= int_info.bits else false,
                .scalar_unsigned_int => |of_is| @divExact(of_is.of.bitSize(cg.target), 8) >= cg.unalignedSize(ty) and
                    if (cg.intInfo(ty.scalarType(zcu))) |int_info| int_info.signedness == .unsigned and
                        of_is.is.bitSize(cg.target) >= int_info.bits else false,
                .exclusive_scalar_int => |of_is| @divExact(of_is.of.bitSize(cg.target), 8) > cg.unalignedSize(ty) and
                    if (cg.intInfo(ty.scalarType(zcu))) |int_info| of_is.is.bitSize(cg.target) >= int_info.bits else false,
                .exclusive_scalar_signed_int => |of_is| @divExact(of_is.of.bitSize(cg.target), 8) > cg.unalignedSize(ty) and
                    if (cg.intInfo(ty.scalarType(zcu))) |int_info| int_info.signedness == .signed and
                        of_is.is.bitSize(cg.target) >= int_info.bits else false,
                .exclusive_scalar_unsigned_int => |of_is| @divExact(of_is.of.bitSize(cg.target), 8) > cg.unalignedSize(ty) and
                    if (cg.intInfo(ty.scalarType(zcu))) |int_info| int_info.signedness == .unsigned and
                        of_is.is.bitSize(cg.target) >= int_info.bits else false,
                .exact_scalar_int => |of_is| @divExact(of_is.of.bitSize(cg.target), 8) == cg.unalignedSize(ty) and
                    if (cg.intInfo(ty.scalarType(zcu))) |int_info| of_is.is.bitSize(cg.target) >= int_info.bits else false,
                .exact_scalar_signed_int => |of_is| @divExact(of_is.of.bitSize(cg.target), 8) == cg.unalignedSize(ty) and
                    if (cg.intInfo(ty.scalarType(zcu))) |int_info| int_info.signedness == .signed and
                        of_is.is.bitSize(cg.target) >= int_info.bits else false,
                .exact_scalar_unsigned_int => |of_is| @divExact(of_is.of.bitSize(cg.target), 8) == cg.unalignedSize(ty) and
                    if (cg.intInfo(ty.scalarType(zcu))) |int_info| int_info.signedness == .unsigned and
                        of_is.is.bitSize(cg.target) >= int_info.bits else false,
                .scalar_signed_or_exclusive_int => |of_is| @divExact(of_is.of.bitSize(cg.target), 8) >= cg.unalignedSize(ty) and
                    if (cg.intInfo(ty)) |int_info| switch (int_info.signedness) {
                        .signed => of_is.is.bitSize(cg.target) >= int_info.bits,
                        .unsigned => of_is.is.bitSize(cg.target) > int_info.bits,
                    } else false,
                .scalar_exact_int => |of_is| @divExact(of_is.of.bitSize(cg.target), 8) >= cg.unalignedSize(ty) and
                    if (cg.intInfo(ty.scalarType(zcu))) |int_info| of_is.is == int_info.bits else false,
                .scalar_exact_signed_int => |of_is| @divExact(of_is.of.bitSize(cg.target), 8) >= cg.unalignedSize(ty) and
                    if (cg.intInfo(ty.scalarType(zcu))) |int_info| int_info.signedness == .signed and
                        of_is.is == int_info.bits else false,
                .scalar_exact_unsigned_int => |of_is| @divExact(of_is.of.bitSize(cg.target), 8) >= cg.unalignedSize(ty) and
                    if (cg.intInfo(ty.scalarType(zcu))) |int_info| int_info.signedness == .unsigned and
                        of_is.is == int_info.bits else false,
                .multiple_scalar => |of_is| ty.abiSize(zcu) % @divExact(of_is.of.bitSize(cg.target), 8) == 0 and
                    if (cg.intInfo(ty.scalarType(zcu))) |int_info|
                        of_is.is.bitSize(cg.target) >= int_info.bits
                    else if (cg.floatBits(ty.scalarType(zcu))) |float_bits|
                        of_is.is.bitSize(cg.target) == float_bits
                    else
                        false,
                .multiple_scalar_int => |of_is| ty.abiSize(zcu) % @divExact(of_is.of.bitSize(cg.target), 8) == 0 and
                    if (cg.intInfo(ty.scalarType(zcu))) |int_info| of_is.is.bitSize(cg.target) >= int_info.bits else false,
                .unaligned_multiple_scalar_int => |of_is| cg.unalignedSize(ty) % @divExact(of_is.of.bitSize(cg.target), 8) == 0 and
                    if (cg.intInfo(ty.scalarType(zcu))) |int_info| of_is.is.bitSize(cg.target) >= int_info.bits else false,
                .unaligned_multiple_scalar_signed_int => |of_is| cg.unalignedSize(ty) % @divExact(of_is.of.bitSize(cg.target), 8) == 0 and
                    if (cg.intInfo(ty.scalarType(zcu))) |int_info| int_info.signedness == .signed and
                        of_is.is.bitSize(cg.target) >= int_info.bits else false,
                .unaligned_multiple_scalar_unsigned_int => |of_is| cg.unalignedSize(ty) % @divExact(of_is.of.bitSize(cg.target), 8) == 0 and
                    if (cg.intInfo(ty.scalarType(zcu))) |int_info| int_info.signedness == .unsigned and
                        of_is.is.bitSize(cg.target) >= int_info.bits else false,
                .multiple_scalar_signed_int => |of_is| ty.abiSize(zcu) % @divExact(of_is.of.bitSize(cg.target), 8) == 0 and
                    if (cg.intInfo(ty.scalarType(zcu))) |int_info| int_info.signedness == .signed and
                        of_is.is.bitSize(cg.target) >= int_info.bits else false,
                .multiple_scalar_unsigned_int => |of_is| ty.abiSize(zcu) % @divExact(of_is.of.bitSize(cg.target), 8) == 0 and
                    if (cg.intInfo(ty.scalarType(zcu))) |int_info| int_info.signedness == .unsigned and
                        of_is.is.bitSize(cg.target) >= int_info.bits else false,
                .multiple_scalar_signed_or_exclusive_int => |of_is| ty.abiSize(zcu) % @divExact(of_is.of.bitSize(cg.target), 8) == 0 and
                    if (cg.intInfo(ty.scalarType(zcu))) |int_info| switch (int_info.signedness) {
                        .signed => of_is.is.bitSize(cg.target) >= int_info.bits,
                        .unsigned => of_is.is.bitSize(cg.target) > int_info.bits,
                    } else false,
                .multiple_scalar_exact_int => |of_is| ty.abiSize(zcu) % @divExact(of_is.of.bitSize(cg.target), 8) == 0 and
                    if (cg.intInfo(ty.scalarType(zcu))) |int_info| of_is.is == int_info.bits else false,
                .multiple_scalar_exact_signed_int => |of_is| ty.abiSize(zcu) % @divExact(of_is.of.bitSize(cg.target), 8) == 0 and
                    if (cg.intInfo(ty.scalarType(zcu))) |int_info| int_info.signedness == .signed and
                        of_is.is == int_info.bits else false,
                .multiple_scalar_exact_unsigned_int => |of_is| ty.abiSize(zcu) % @divExact(of_is.of.bitSize(cg.target), 8) == 0 and
                    if (cg.intInfo(ty.scalarType(zcu))) |int_info| int_info.signedness == .unsigned and
                        of_is.is == int_info.bits else false,
                .scalar_remainder_int => |of_is| if (cg.intInfo(ty.scalarType(zcu))) |int_info|
                    of_is.is.bitSize(cg.target) >= (int_info.bits - 1) % of_is.of.bitSize(cg.target) + 1
                else
                    false,
                .scalar_remainder_signed_int => |of_is| if (cg.intInfo(ty.scalarType(zcu))) |int_info| int_info.signedness == .signed and
                    of_is.is.bitSize(cg.target) >= (int_info.bits - 1) % of_is.of.bitSize(cg.target) + 1 else false,
                .scalar_remainder_unsigned_int => |of_is| if (cg.intInfo(ty.scalarType(zcu))) |int_info| int_info.signedness == .unsigned and
                    of_is.is.bitSize(cg.target) >= (int_info.bits - 1) % of_is.of.bitSize(cg.target) + 1 else false,
                .scalar_exact_remainder_int => |of_is| if (cg.intInfo(ty.scalarType(zcu))) |int_info|
                    of_is.is.bitSize(cg.target) == (int_info.bits - 1) % of_is.of.bitSize(cg.target) + 1
                else
                    false,
                .scalar_exact_remainder_signed_int => |of_is| if (cg.intInfo(ty.scalarType(zcu))) |int_info| int_info.signedness == .signed and
                    of_is.is.bitSize(cg.target) == (int_info.bits - 1) % of_is.of.bitSize(cg.target) + 1 else false,
                .scalar_exact_remainder_unsigned_int => |of_is| if (cg.intInfo(ty.scalarType(zcu))) |int_info| int_info.signedness == .unsigned and
                    of_is.is.bitSize(cg.target) == (int_info.bits - 1) % of_is.of.bitSize(cg.target) + 1 else false,
                .float => |size| if (cg.floatBits(ty)) |float_bits| size.bitSize(cg.target) == float_bits else false,
                .scalar_any_float => |size| @divExact(size.bitSize(cg.target), 8) >= ty.abiSize(zcu) and
                    cg.floatBits(ty.scalarType(zcu)) != null,
                .scalar_float => |of_is| @divExact(of_is.of.bitSize(cg.target), 8) >= cg.unalignedSize(ty) and
                    if (cg.floatBits(ty.scalarType(zcu))) |float_bits| of_is.is.bitSize(cg.target) == float_bits else false,
                .exclusive_scalar_float => |of_is| @divExact(of_is.of.bitSize(cg.target), 8) > cg.unalignedSize(ty) and
                    if (cg.floatBits(ty.scalarType(zcu))) |float_bits| of_is.is.bitSize(cg.target) == float_bits else false,
                .exact_scalar_float => |of_is| @divExact(of_is.of.bitSize(cg.target), 8) == cg.unalignedSize(ty) and
                    if (cg.floatBits(ty.scalarType(zcu))) |float_bits| of_is.is.bitSize(cg.target) == float_bits else false,
                .multiple_scalar_any_float => |size| ty.abiSize(zcu) % @divExact(size.bitSize(cg.target), 8) == 0 and
                    cg.floatBits(ty.scalarType(zcu)) != null,
                .multiple_scalar_float => |of_is| ty.abiSize(zcu) % @divExact(of_is.of.bitSize(cg.target), 8) == 0 and
                    if (cg.floatBits(ty.scalarType(zcu))) |float_bits| of_is.is.bitSize(cg.target) == float_bits else false,
                .unaligned_multiple_scalar_float => |of_is| cg.unalignedSize(ty) % @divExact(of_is.of.bitSize(cg.target), 8) == 0 and
                    if (cg.floatBits(ty.scalarType(zcu))) |float_bits| of_is.is.bitSize(cg.target) == float_bits else false,
                .exact_int => |bit_size| if (cg.intInfo(ty)) |int_info| bit_size == int_info.bits else false,
                .exact_signed_int => |bit_size| if (cg.intInfo(ty)) |int_info| switch (int_info.signedness) {
                    .signed => bit_size == int_info.bits,
                    .unsigned => false,
                } else false,
                .exact_unsigned_int => |bit_size| if (cg.intInfo(ty)) |int_info| switch (int_info.signedness) {
                    .signed => false,
                    .unsigned => bit_size == int_info.bits,
                } else false,
                .signed_or_exact_int => |size| if (cg.intInfo(ty)) |int_info| switch (int_info.signedness) {
                    .signed => size.bitSize(cg.target) >= int_info.bits,
                    .unsigned => size.bitSize(cg.target) == int_info.bits,
                } else false,
                .unsigned_or_exact_int => |size| if (cg.intInfo(ty)) |int_info| switch (int_info.signedness) {
                    .signed => size.bitSize(cg.target) == int_info.bits,
                    .unsigned => size.bitSize(cg.target) >= int_info.bits,
                } else false,
                .signed_or_exclusive_int => |size| if (cg.intInfo(ty)) |int_info| switch (int_info.signedness) {
                    .signed => size.bitSize(cg.target) >= int_info.bits,
                    .unsigned => size.bitSize(cg.target) > int_info.bits,
                } else false,
                .po2_int => |size| if (cg.intInfo(ty)) |int_info|
                    std.math.isPowerOfTwo(int_info.bits) and size.bitSize(cg.target) >= int_info.bits
                else
                    false,
                .signed_po2_int => |size| if (cg.intInfo(ty)) |int_info| switch (int_info.signedness) {
                    .signed => std.math.isPowerOfTwo(int_info.bits) and size.bitSize(cg.target) >= int_info.bits,
                    .unsigned => false,
                } else false,
                .unsigned_po2_or_exact_int => |size| if (cg.intInfo(ty)) |int_info| switch (int_info.signedness) {
                    .signed => size.bitSize(cg.target) == int_info.bits,
                    .unsigned => std.math.isPowerOfTwo(int_info.bits) and size.bitSize(cg.target) >= int_info.bits,
                } else false,
                .remainder_int => |of_is| if (cg.intInfo(ty)) |int_info|
                    of_is.is.bitSize(cg.target) >= (int_info.bits - 1) % of_is.of.bitSize(cg.target) + 1
                else
                    false,
                .remainder_signed_int => |of_is| if (cg.intInfo(ty)) |int_info| int_info.signedness == .signed and
                    of_is.is.bitSize(cg.target) >= (int_info.bits - 1) % of_is.of.bitSize(cg.target) + 1 else false,
                .remainder_unsigned_int => |of_is| if (cg.intInfo(ty)) |int_info| int_info.signedness == .unsigned and
                    of_is.is.bitSize(cg.target) >= (int_info.bits - 1) % of_is.of.bitSize(cg.target) + 1 else false,
                .exact_remainder_int => |of_is| if (cg.intInfo(ty)) |int_info|
                    of_is.is == (int_info.bits - 1) % of_is.of.bitSize(cg.target) + 1
                else
                    false,
                .exact_remainder_signed_int => |of_is| if (cg.intInfo(ty)) |int_info| int_info.signedness == .signed and
                    of_is.is == (int_info.bits - 1) % of_is.of.bitSize(cg.target) + 1 else false,
                .exact_remainder_unsigned_int => |of_is| if (cg.intInfo(ty)) |int_info| int_info.signedness == .unsigned and
                    of_is.is == (int_info.bits - 1) % of_is.of.bitSize(cg.target) + 1 else false,
                .signed_or_exact_remainder_int => |of_is| if (cg.intInfo(ty)) |int_info| switch (int_info.signedness) {
                    .signed => of_is.is.bitSize(cg.target) >= (int_info.bits - 1) % of_is.of.bitSize(cg.target) + 1,
                    .unsigned => of_is.is.bitSize(cg.target) == (int_info.bits - 1) % of_is.of.bitSize(cg.target) + 1,
                } else false,
                .unsigned_or_exact_remainder_int => |of_is| if (cg.intInfo(ty)) |int_info| switch (int_info.signedness) {
                    .signed => of_is.is.bitSize(cg.target) == (int_info.bits - 1) % of_is.of.bitSize(cg.target) + 1,
                    .unsigned => of_is.is.bitSize(cg.target) >= (int_info.bits - 1) % of_is.of.bitSize(cg.target) + 1,
                } else false,
                .signed_int => |size| if (cg.intInfo(ty)) |int_info| switch (int_info.signedness) {
                    .signed => size.bitSize(cg.target) >= int_info.bits,
                    .unsigned => false,
                } else false,
                .unsigned_int => |size| if (cg.intInfo(ty)) |int_info| switch (int_info.signedness) {
                    .signed => false,
                    .unsigned => size.bitSize(cg.target) >= int_info.bits,
                } else false,
                .elem_size_is => |size| size == ty.elemType2(zcu).abiSize(zcu),
                .po2_elem_size => std.math.isPowerOfTwo(ty.elemType2(zcu).abiSize(zcu)),
                .elem_int => |size| if (cg.intInfo(ty.elemType2(zcu))) |elem_int_info|
                    size.bitSize(cg.target) >= elem_int_info.bits
                else
                    false,
            };
        }
    };

    const Pattern = struct {
        src: [@intFromEnum(Select.Operand.Ref.none) - @intFromEnum(Select.Operand.Ref.src0)]Src,
        commute: struct { u8, u8 } = .{ 0, 0 },

        const Src = union(enum) {
            none,
            any,
            imm: i16,
            imm8,
            imm16,
            imm32,
            simm32,
            to_reg: Register,
            to_reg_pair: [2]Register,
            to_param_gpr: TempSpec.Kind.CallConvRegSpec,
            to_param_gpr_pair: TempSpec.Kind.CallConvRegSpec,
            to_param_sse: TempSpec.Kind.CallConvRegSpec,
            to_ret_gpr: TempSpec.Kind.CallConvRegSpec,
            to_ret_gpr_pair: TempSpec.Kind.CallConvRegSpec,
            mem,
            to_mem,
            mut_mem,
            to_mut_mem,
            gpr,
            immut_gpr,
            to_gpr,
            mut_gpr,
            to_mut_gpr,
            to_gphi,
            to_mut_gphi,
            x87,
            to_x87,
            mut_x87,
            to_mut_x87,
            mmx,
            to_mmx,
            mut_mmx,
            to_mut_mmx,
            sse,
            to_sse,
            mut_sse,
            to_mut_sse,
            reg_mask: RegMaskSpec,
            all_reg_mask: RegMaskSpec,

            const RegMaskSpec = struct {
                size: Memory.Size,
                is: enum {
                    any,
                    uninverted,
                    inverted,

                    fn matches(is: @This(), inverted: bool) bool {
                        return switch (is) {
                            .any => true,
                            .uninverted => !inverted,
                            .inverted => inverted,
                        };
                    }
                } = .any,
            };

            fn matches(src: Src, temp: Temp, cg: *CodeGen) bool {
                return switch (src) {
                    .none => temp.tracking(cg).short == .none,
                    .any => true,
                    .imm => |specific_imm| switch (temp.tracking(cg).short) {
                        .immediate => |imm| @as(i64, @bitCast(imm)) == specific_imm,
                        else => false,
                    },
                    .imm8 => switch (temp.tracking(cg).short) {
                        .immediate => |imm| std.math.cast(u8, imm) != null or
                            std.math.cast(i8, @as(i64, @bitCast(imm))) != null,
                        else => false,
                    },
                    .imm16 => switch (temp.tracking(cg).short) {
                        .immediate => |imm| std.math.cast(u16, imm) != null or
                            std.math.cast(i16, @as(i64, @bitCast(imm))) != null,
                        else => false,
                    },
                    .imm32 => switch (temp.tracking(cg).short) {
                        .immediate => |imm| std.math.cast(u32, imm) != null or
                            std.math.cast(i32, @as(i64, @bitCast(imm))) != null,
                        else => false,
                    },
                    .simm32 => switch (temp.tracking(cg).short) {
                        .immediate => |imm| std.math.cast(i32, @as(i64, @bitCast(imm))) != null,
                        else => false,
                    },
                    .mem => temp.tracking(cg).short.isMemory(),
                    .to_mem, .to_mut_mem => true,
                    .mut_mem => temp.isMut(cg) and temp.tracking(cg).short.isMemory(),
                    .to_reg, .to_reg_pair, .to_param_gpr, .to_param_gpr_pair, .to_param_sse, .to_ret_gpr, .to_ret_gpr_pair => true,
                    .gpr => temp.typeOf(cg).abiSize(cg.pt.zcu) <= 8 and switch (temp.tracking(cg).short) {
                        .register => |reg| reg.isClass(.general_purpose),
                        .register_offset => |reg_off| reg_off.reg.isClass(.general_purpose) and reg_off.off == 0,
                        else => false,
                    },
                    .immut_gpr => !temp.isMut(cg) and temp.typeOf(cg).abiSize(cg.pt.zcu) <= 8 and switch (temp.tracking(cg).short) {
                        .register => |reg| reg.isClass(.general_purpose),
                        .register_offset => |reg_off| reg_off.reg.isClass(.general_purpose) and reg_off.off == 0,
                        else => false,
                    },
                    .mut_gpr => temp.isMut(cg) and temp.typeOf(cg).abiSize(cg.pt.zcu) <= 8 and switch (temp.tracking(cg).short) {
                        .register => |reg| reg.isClass(.general_purpose),
                        .register_offset => |reg_off| reg_off.reg.isClass(.general_purpose) and reg_off.off == 0,
                        else => false,
                    },
                    .to_gpr, .to_mut_gpr, .to_gphi, .to_mut_gphi => temp.typeOf(cg).abiSize(cg.pt.zcu) <= 8,
                    .x87 => switch (temp.tracking(cg).short) {
                        .register => |reg| reg.isClass(.x87),
                        .register_offset => |reg_off| reg_off.reg.isClass(.x87) and reg_off.off == 0,
                        else => false,
                    },
                    .mut_x87 => temp.isMut(cg) and switch (temp.tracking(cg).short) {
                        .register => |reg| reg.isClass(.x87),
                        .register_offset => |reg_off| reg_off.reg.isClass(.x87) and reg_off.off == 0,
                        else => false,
                    },
                    .to_x87, .to_mut_x87 => true,
                    .mmx => switch (temp.tracking(cg).short) {
                        .register => |reg| reg.isClass(.mmx),
                        .register_offset => |reg_off| reg_off.reg.isClass(.mmx) and reg_off.off == 0,
                        else => false,
                    },
                    .mut_mmx => temp.isMut(cg) and switch (temp.tracking(cg).short) {
                        .register => |reg| reg.isClass(.mmx),
                        .register_offset => |reg_off| reg_off.reg.isClass(.mmx) and reg_off.off == 0,
                        else => false,
                    },
                    .to_mmx, .to_mut_mmx => true,
                    .sse => switch (temp.tracking(cg).short) {
                        .register => |reg| reg.isClass(.sse),
                        .register_offset => |reg_off| reg_off.reg.isClass(.sse) and reg_off.off == 0,
                        else => false,
                    },
                    .mut_sse => temp.isMut(cg) and switch (temp.tracking(cg).short) {
                        .register => |reg| reg.isClass(.sse),
                        .register_offset => |reg_off| reg_off.reg.isClass(.sse) and reg_off.off == 0,
                        else => false,
                    },
                    .to_sse, .to_mut_sse => true,
                    .reg_mask => |mask_spec| switch (temp.tracking(cg).short) {
                        .register_mask => |reg_mask| mask_spec.size.bitSize(cg.target) >=
                            reg_mask.info.scalar.bitSize(cg.target) * temp.typeOf(cg).vectorLen(cg.pt.zcu) and
                            mask_spec.is.matches(reg_mask.info.inverted),
                        else => false,
                    },
                    .all_reg_mask => |mask_spec| switch (temp.tracking(cg).short) {
                        .register_mask => |reg_mask| mask_spec.size.bitSize(cg.target) ==
                            reg_mask.info.scalar.bitSize(cg.target) * temp.typeOf(cg).vectorLen(cg.pt.zcu) and
                            reg_mask.info.kind == .all and mask_spec.is.matches(reg_mask.info.inverted),
                        else => false,
                    },
                };
            }

            fn convert(src: Src, temp: *Temp, cg: *CodeGen) InnerError!bool {
                return switch (src) {
                    .none, .any, .imm, .imm8, .imm16, .imm32, .simm32, .reg_mask, .all_reg_mask => false,
                    .mem, .to_mem => try temp.toBase(false, cg),
                    .mut_mem, .to_mut_mem => try temp.toBase(true, cg),
                    .to_reg => |reg| try temp.toReg(reg, cg),
                    .to_reg_pair => |regs| try temp.toRegPair(regs, cg),
                    .to_param_gpr => |param_spec| try temp.toReg(abi.getCAbiIntParamRegs(param_spec.tag(cg))[param_spec.index(cg)], cg),
                    .to_param_gpr_pair => |param_spec| try temp.toRegPair(abi.getCAbiIntParamRegs(param_spec.tag(cg))[param_spec.index(cg)..][0..2].*, cg),
                    .to_param_sse => |param_spec| try temp.toReg(abi.getCAbiSseParamRegs(param_spec.tag(cg), cg.target)[param_spec.index(cg)], cg),
                    .to_ret_gpr => |ret_spec| try temp.toReg(abi.getCAbiIntReturnRegs(ret_spec.tag(cg))[ret_spec.index(cg)], cg),
                    .to_ret_gpr_pair => |ret_spec| try temp.toRegPair(abi.getCAbiIntReturnRegs(ret_spec.tag(cg))[ret_spec.index(cg)..][0..2].*, cg),
                    .gpr, .immut_gpr, .to_gpr => try temp.toRegClass(false, .general_purpose, cg),
                    .mut_gpr, .to_mut_gpr => try temp.toRegClass(true, .general_purpose, cg),
                    .to_gphi => try temp.toRegClass(false, .gphi, cg),
                    .to_mut_gphi => try temp.toRegClass(true, .gphi, cg),
                    .x87, .to_x87 => try temp.toRegClass(false, .x87, cg),
                    .mut_x87, .to_mut_x87 => try temp.toRegClass(true, .x87, cg),
                    .mmx, .to_mmx => try temp.toRegClass(false, .mmx, cg),
                    .mut_mmx, .to_mut_mmx => try temp.toRegClass(true, .mmx, cg),
                    .sse, .to_sse => try temp.toRegClass(false, .sse, cg),
                    .mut_sse, .to_mut_sse => try temp.toRegClass(true, .sse, cg),
                };
            }
        };
    };

    const TempSpec = struct {
        type: Type = .noreturn,
        kind: Kind,

        const unused: TempSpec = .{ .kind = .unused };

        const Kind = union(enum) {
            unused,
            any,
            none,
            undef,
            cc: Condition,
            ptest_cc: struct { ref: Select.Operand.Ref, not: bool = false, all: u1 },
            imm: i32,
            ref: Select.Operand.Ref,
            reg: Register,
            reg_pair: [2]Register,
            param_gpr: CallConvRegSpec,
            param_gpr_pair: CallConvRegSpec,
            param_sse: CallConvRegSpec,
            ret_gpr: CallConvRegSpec,
            ret_gpr_pair: CallConvRegSpec,
            ret_sse: CallConvRegSpec,
            rc: Register.Class,
            rc_pair: Register.Class,
            mut_rc: struct { ref: Select.Operand.Ref, rc: Register.Class },
            ref_mask: struct { ref: Select.Operand.Ref, info: MaskInfo },
            rc_mask: struct { rc: Register.Class, info: MaskInfo },
            mut_rc_mask: struct { ref: Select.Operand.Ref, rc: Register.Class, info: MaskInfo },
            mem,
            mem_of_type: Select.Operand.Ref,
            smin_mem: ConstSpec,
            smax_mem: ConstSpec,
            slimit_delta_mem: ConstSpec,
            umin_mem: ConstSpec,
            umax_mem: ConstSpec,
            umax_delta_mem: ConstSpec,
            @"0x1p63_mem": ConstSpec,
            f64_0x1p52_0x1p84_mem,
            u32_0x1p52_hi_0x1p84_hi_0_0_mem,
            f32_0_0x1p64_mem,
            pshufb_splat_mem: struct { of: Memory.Size = .none, size: Memory.Size },
            pshufb_trunc_mem: struct { of: Memory.Size = .none, from: Memory.Size, to: Memory.Size },
            pand_trunc_mem: struct { from: Memory.Size, to: Memory.Size },
            pand_mask_mem: struct { ref: Select.Operand.Ref, invert: bool = false },
            ptest_mask_mem: Select.Operand.Ref,
            pshufb_bswap_mem: struct { repeat: u4 = 1, size: Memory.Size, smear: u4 = 1 },
            bits_mem: enum { forward, reverse },
            splat_int_mem: struct { ref: Select.Operand.Ref, inside: enum { umin, smin, smax } = .umin, outside: enum { smin, smax } },
            splat_float_mem: struct { ref: Select.Operand.Ref, inside: enum { zero } = .zero, outside: f16 },
            frame: FrameIndex,
            lazy_sym: struct { kind: link.File.LazySymbol.Kind, ref: Select.Operand.Ref = .none },
            extern_func: [*:0]const u8,

            const ConstSpec = struct {
                ref: Select.Operand.Ref = .none,
                to_signedness: ?std.builtin.Signedness = null,
                vectorize_to: ?Memory.Size = null,
            };

            const CallConvRegSpec = struct {
                cc: Case.CallConv,
                after: u2,
                at: u2,

                fn tag(spec: CallConvRegSpec, cg: *const CodeGen) std.builtin.CallingConvention.Tag {
                    return switch (spec.cc) {
                        .none => unreachable,
                        .ccc => cg.target.cCallingConvention().?,
                        .zigcc => .auto,
                    };
                }

                fn index(spec: CallConvRegSpec, cg: *const CodeGen) u2 {
                    return switch (spec.tag(cg)) {
                        .auto, .x86_64_sysv => spec.after,
                        .x86_64_win => spec.at,
                        else => unreachable,
                    };
                }
            };

            fn lock(kind: Kind, cg: *CodeGen) ![2]?RegisterLock {
                var reg_locks: [2]?RegisterLock = @splat(null);
                const regs: [2]Register = switch (kind) {
                    else => return reg_locks,
                    .reg => |reg| .{ reg, .none },
                    .reg_pair => |regs| regs,
                    .param_gpr => |param_spec| abi.getCAbiIntParamRegs(param_spec.tag(cg))[param_spec.index(cg)..][0..1].* ++ .{.none},
                    .param_gpr_pair => |param_spec| abi.getCAbiIntParamRegs(param_spec.tag(cg))[param_spec.index(cg)..][0..2].*,
                    .param_sse => |param_spec| abi.getCAbiSseParamRegs(param_spec.tag(cg), cg.target)[param_spec.index(cg)..][0..1].* ++ .{.none},
                    .ret_gpr => |ret_spec| abi.getCAbiIntReturnRegs(ret_spec.tag(cg))[ret_spec.index(cg)..][0..1].* ++ .{.none},
                    .ret_gpr_pair => |ret_spec| abi.getCAbiIntReturnRegs(ret_spec.tag(cg))[ret_spec.index(cg)..][0..2].*,
                    .ret_sse => |ret_spec| abi.getCAbiSseReturnRegs(ret_spec.tag(cg))[ret_spec.index(cg)..][0..1].* ++ .{.none},
                };
                for (regs, &reg_locks) |reg, *reg_lock| {
                    if (reg == .none) continue;
                    const reg_index = RegisterManager.indexOfRegIntoTracked(reg) orelse continue;
                    try cg.register_manager.getRegIndex(reg_index, null);
                    reg_lock.* = cg.register_manager.lockRegIndex(reg_index);
                }
                return reg_locks;
            }
        };

        fn create(spec: TempSpec, s: *const Select) InnerError!struct { Temp, bool } {
            const cg = s.cg;
            const pt = cg.pt;
            return switch (spec.kind) {
                .unused => .{ undefined, false },
                .any => .{ try cg.tempAlloc(spec.type), true },
                .none => .{ try cg.tempInit(spec.type, .none), true },
                .undef => .{ try cg.tempInit(spec.type, .undef), true },
                .imm => |imm| .{ try cg.tempInit(spec.type, .{ .immediate = @bitCast(@as(i64, imm)) }), true },
                .cc => |cc| .{ try cg.tempInit(spec.type, .{ .eflags = cc }), true },
                .ptest_cc => |cc_spec| {
                    const ccs: [2]Condition = .{ .z, .c };
                    const cc = ccs[cc_spec.all ^ @intFromBool(cc_spec.ref.valueOf(s).register_mask.info.inverted)];
                    return .{ try cg.tempInit(spec.type, .{ .eflags = switch (cc_spec.not) {
                        false => cc,
                        true => cc.negate(),
                    } }), true };
                },
                .ref => |ref| .{ ref.tempOf(s), false },
                .reg => |reg| .{ try cg.tempInit(spec.type, .{ .register = reg }), true },
                .reg_pair => |regs| .{ try cg.tempInit(spec.type, .{ .register_pair = regs }), true },
                .param_gpr => |param_spec| .{ try cg.tempInit(spec.type, .{
                    .register = abi.getCAbiIntParamRegs(param_spec.tag(cg))[param_spec.index(cg)],
                }), true },
                .param_gpr_pair => |param_spec| .{ try cg.tempInit(spec.type, .{
                    .register_pair = abi.getCAbiIntParamRegs(param_spec.tag(cg))[param_spec.index(cg)..][0..2].*,
                }), true },
                .param_sse => |param_spec| .{ try cg.tempInit(spec.type, .{
                    .register = abi.getCAbiSseParamRegs(param_spec.tag(cg), cg.target)[param_spec.index(cg)],
                }), true },
                .ret_gpr => |ret_spec| .{ try cg.tempInit(spec.type, .{
                    .register = abi.getCAbiIntReturnRegs(ret_spec.tag(cg))[ret_spec.index(cg)],
                }), true },
                .ret_gpr_pair => |ret_spec| .{ try cg.tempInit(spec.type, .{
                    .register_pair = abi.getCAbiIntReturnRegs(ret_spec.tag(cg))[ret_spec.index(cg)..][0..2].*,
                }), true },
                .ret_sse => |ret_spec| .{ try cg.tempInit(spec.type, .{
                    .register = abi.getCAbiSseReturnRegs(ret_spec.tag(cg))[ret_spec.index(cg)],
                }), true },
                .rc => |rc| .{ try cg.tempAllocReg(spec.type, regSetForRegClass(rc)), true },
                .rc_pair => |rc| .{ try cg.tempAllocRegPair(spec.type, regSetForRegClass(rc)), true },
                .mut_rc => |ref_rc| {
                    const temp = ref_rc.ref.tempOf(s);
                    if (temp.isMut(cg)) switch (temp.tracking(cg).short) {
                        .register => |reg| if (reg.isClass(ref_rc.rc)) return .{ temp, false },
                        .register_offset => |reg_off| if (reg_off.off == 0 and reg_off.reg.isClass(ref_rc.rc)) return .{ temp, false },
                        else => {},
                    };
                    return .{ try cg.tempAllocReg(spec.type, regSetForRegClass(ref_rc.rc)), true };
                },
                .ref_mask => |ref_mask| .{ ref_mask.ref.tempOf(s), false },
                .rc_mask => |rc_mask| .{ try cg.tempAllocReg(spec.type, regSetForRegClass(rc_mask.rc)), true },
                .mut_rc_mask => |ref_rc_mask| {
                    const temp = ref_rc_mask.ref.tempOf(s);
                    if (temp.isMut(cg)) switch (temp.tracking(cg).short) {
                        .register => |reg| if (reg.isClass(ref_rc_mask.rc)) return .{ temp, false },
                        .register_offset => |reg_off| if (reg_off.off == 0 and reg_off.reg.isClass(ref_rc_mask.rc)) return .{ temp, false },
                        else => {},
                    };
                    return .{ try cg.tempAllocReg(spec.type, regSetForRegClass(ref_rc_mask.rc)), true };
                },
                .mem => .{ try cg.tempAllocMem(spec.type), true },
                .mem_of_type => |ref| .{ try cg.tempAllocMem(ref.typeOf(s)), true },
                .smin_mem,
                .smax_mem,
                .slimit_delta_mem,
                .umin_mem,
                .umax_mem,
                .umax_delta_mem,
                .@"0x1p63_mem",
                => |const_spec| {
                    const zcu = pt.zcu;
                    const ip = &zcu.intern_pool;
                    const ty = if (const_spec.ref == .none) spec.type else const_spec.ref.typeOf(s);
                    const vector_len, const scalar_ty: Type = switch (ip.indexToKey(ty.toIntern())) {
                        else => .{ null, ty },
                        .vector_type => |vector_type| .{ vector_type.len, .fromInterned(vector_type.child) },
                    };
                    const res_vector_len: ?u32 = if (const_spec.vectorize_to) |vectorize_to| switch (vectorize_to) {
                        .none => null,
                        else => @intCast(@divExact(@divExact(vectorize_to.bitSize(cg.target), 8), scalar_ty.abiSize(pt.zcu))),
                    } else vector_len;
                    const res_scalar_ty, const res_scalar_val: Value = res_scalar: switch (scalar_ty.toIntern()) {
                        .bool_type => .{ scalar_ty, .fromInterned(switch (spec.kind) {
                            else => unreachable,
                            .smin_mem, .umax_mem => .bool_true,
                            .smax_mem, .umin_mem => .bool_false,
                        }) },
                        else => {
                            const scalar_info: std.builtin.Type.Int = cg.intInfo(scalar_ty) orelse .{
                                .signedness = .signed,
                                .bits = cg.floatBits(scalar_ty).?,
                            };
                            const res_scalar_info: std.builtin.Type.Int = .{
                                .signedness = const_spec.to_signedness orelse scalar_info.signedness,
                                .bits = switch (spec.kind) {
                                    else => scalar_info.bits,
                                    .slimit_delta_mem, .umax_delta_mem => cg.intInfo(spec.type.scalarType(zcu)).?.bits,
                                },
                            };
                            const res_scalar_ty = try pt.intType(res_scalar_info.signedness, res_scalar_info.bits);

                            if (res_scalar_info.bits <= 64) {
                                const int_val: i64 = switch (spec.kind) {
                                    else => unreachable,
                                    .smin_mem => std.math.minInt(i64),
                                    .smax_mem => std.math.maxInt(i64),
                                    .slimit_delta_mem => std.math.maxInt(i64) -
                                        (@as(i64, std.math.maxInt(i64)) >> @intCast(res_scalar_info.bits - scalar_info.bits)),
                                    .umin_mem => 0,
                                    .umax_mem => -1,
                                    .umax_delta_mem => @bitCast(std.math.maxInt(u64) -
                                        (@as(u64, std.math.maxInt(u64)) >> @intCast(res_scalar_info.bits - scalar_info.bits))),
                                    .@"0x1p63_mem" => switch (res_scalar_info.bits) {
                                        else => unreachable,
                                        16 => @as(i64, @as(i16, @bitCast(@as(f16, 0x1p63)))) << 64 - 16,
                                        32 => @as(i64, @as(i32, @bitCast(@as(f32, 0x1p63)))) << 64 - 32,
                                        64 => @as(i64, @as(i64, @bitCast(@as(f64, 0x1p63)))) << 64 - 64,
                                    },
                                };
                                const shift: u6 = @intCast(64 - res_scalar_info.bits);
                                break :res_scalar .{ res_scalar_ty, switch (res_scalar_info.signedness) {
                                    .signed => try pt.intValue_i64(res_scalar_ty, int_val >> shift),
                                    .unsigned => try pt.intValue_u64(res_scalar_ty, @as(u64, @bitCast(int_val)) >> shift),
                                } };
                            }

                            const ExpectedContents = [std.math.big.int.calcTwosCompLimbCount(1 << 10)]std.math.big.Limb;
                            var stack align(@max(@alignOf(ExpectedContents), @alignOf(std.heap.StackFallbackAllocator(0)))) =
                                std.heap.stackFallback(@sizeOf(ExpectedContents), cg.gpa);
                            const allocator = stack.get();
                            var res_big_int: std.math.big.int.Mutable = .{
                                .limbs = try allocator.alloc(
                                    std.math.big.Limb,
                                    std.math.big.int.calcTwosCompLimbCount(res_scalar_info.bits),
                                ),
                                .len = undefined,
                                .positive = undefined,
                            };
                            defer allocator.free(res_big_int.limbs);
                            switch (spec.kind) {
                                else => unreachable,
                                .smin_mem, .smax_mem, .umin_mem, .umax_mem => res_big_int.setTwosCompIntLimit(switch (spec.kind) {
                                    else => unreachable,
                                    .smin_mem, .umin_mem => .min,
                                    .smax_mem, .umax_mem => .max,
                                }, switch (spec.kind) {
                                    else => unreachable,
                                    .smin_mem, .smax_mem => .signed,
                                    .umin_mem, .umax_mem => .unsigned,
                                }, res_scalar_info.bits),
                                .slimit_delta_mem, .umax_delta_mem => {
                                    var big_int: std.math.big.int.Mutable = .{
                                        .limbs = try allocator.alloc(
                                            std.math.big.Limb,
                                            std.math.big.int.calcTwosCompLimbCount(scalar_info.bits),
                                        ),
                                        .len = undefined,
                                        .positive = undefined,
                                    };
                                    defer allocator.free(big_int.limbs);
                                    const signedness: std.builtin.Signedness = switch (spec.kind) {
                                        else => unreachable,
                                        .slimit_delta_mem => .signed,
                                        .umax_delta_mem => .unsigned,
                                    };
                                    big_int.setTwosCompIntLimit(.max, signedness, scalar_info.bits);
                                    res_big_int.setTwosCompIntLimit(.max, signedness, res_scalar_info.bits);
                                    res_big_int.sub(res_big_int.toConst(), big_int.toConst());
                                },
                                .@"0x1p63_mem" => switch (res_scalar_info.bits) {
                                    else => unreachable,
                                    80 => res_big_int.set(@as(u80, @bitCast(@as(f80, 0x1p63)))),
                                    128 => res_big_int.set(@as(u128, @bitCast(@as(f128, 0x1p63)))),
                                },
                            }
                            res_big_int.truncate(res_big_int.toConst(), res_scalar_info.signedness, res_scalar_info.bits);
                            break :res_scalar .{ res_scalar_ty, try pt.intValue_big(res_scalar_ty, res_big_int.toConst()) };
                        },
                    };
                    const res_val = if (res_vector_len) |len| try pt.aggregateSplatValue(try pt.vectorType(.{
                        .len = len,
                        .child = res_scalar_ty.toIntern(),
                    }), res_scalar_val) else res_scalar_val;
                    return .{ try cg.tempMemFromValue(res_val), true };
                },
                .f64_0x1p52_0x1p84_mem => .{ try cg.tempMemFromValue(
                    try pt.aggregateValue(try pt.vectorType(.{ .len = 2, .child = .f64_type }), &.{
                        (try pt.floatValue(.f64, @as(f64, 0x1p52))).toIntern(),
                        (try pt.floatValue(.f64, @as(f64, 0x1p84))).toIntern(),
                    }),
                ), true },
                .u32_0x1p52_hi_0x1p84_hi_0_0_mem => .{ try cg.tempMemFromValue(
                    try pt.aggregateValue(try pt.vectorType(.{ .len = 4, .child = .u32_type }), &(.{
                        (try pt.intValue(.u32, @as(u64, @bitCast(@as(f64, 0x1p52))) >> 32)).toIntern(),
                        (try pt.intValue(.u32, @as(u64, @bitCast(@as(f64, 0x1p84))) >> 32)).toIntern(),
                    } ++ .{(try pt.intValue(.u32, 0)).toIntern()} ** 2)),
                ), true },
                .f32_0_0x1p64_mem => .{ try cg.tempMemFromValue(
                    try pt.aggregateValue(try pt.vectorType(.{ .len = 2, .child = .f32_type }), &.{
                        (try pt.floatValue(.f32, @as(f32, 0))).toIntern(),
                        (try pt.floatValue(.f32, @as(f32, 0x1p64))).toIntern(),
                    }),
                ), true },
                .pshufb_splat_mem => |splat_spec| {
                    const zcu = pt.zcu;
                    assert(spec.type.isVector(zcu) and spec.type.childType(zcu).toIntern() == .u8_type);
                    var elem_buf: [32]u8 = @splat(1 << 7);
                    const elems = elem_buf[0..spec.type.vectorLen(zcu)];
                    const of_bytes: u6 = @intCast(switch (splat_spec.of) {
                        .none => elems.len,
                        else => |of| @divExact(of.bitSize(cg.target), 8),
                    });
                    const size_bytes: u6 = @intCast(@divExact(splat_spec.size.bitSize(cg.target), 8));
                    var index: u6 = 0;
                    while (index < of_bytes) : (index += size_bytes) for (0..size_bytes) |byte_off| {
                        elems[index + byte_off] = @as(u4, @truncate(byte_off));
                    };
                    return .{ try cg.tempMemFromValue(.fromInterned(try pt.intern(.{ .aggregate = .{
                        .ty = spec.type.toIntern(),
                        .storage = .{ .bytes = try zcu.intern_pool.getOrPutString(zcu.gpa, pt.tid, elems, .maybe_embedded_nulls) },
                    } }))), true };
                },
                .pshufb_trunc_mem => |trunc_spec| {
                    const zcu = pt.zcu;
                    assert(spec.type.isVector(zcu) and spec.type.childType(zcu).toIntern() == .u8_type);
                    var elem_buf: [32]u8 = @splat(1 << 7);
                    const elems = elem_buf[0..spec.type.vectorLen(zcu)];
                    const of_bytes: u6 = @intCast(switch (trunc_spec.of) {
                        .none => elems.len,
                        else => |of| @divExact(of.bitSize(cg.target), 8),
                    });
                    const from_bytes: u5 = @intCast(@divExact(trunc_spec.from.bitSize(cg.target), 8));
                    const to_bytes: u5 = @intCast(@divExact(trunc_spec.to.bitSize(cg.target), 8));
                    var from_index: u6 = 0;
                    var to_index: u6 = 0;
                    while (from_index < of_bytes) : ({
                        from_index += from_bytes;
                        switch (from_index % 16) {
                            0 => to_index = from_index,
                            else => to_index += to_bytes,
                        }
                    }) for (0..to_bytes) |byte_off| {
                        elems[to_index + byte_off] = @as(u4, @truncate(from_index + byte_off));
                    };
                    return .{ try cg.tempMemFromValue(.fromInterned(try pt.intern(.{ .aggregate = .{
                        .ty = spec.type.toIntern(),
                        .storage = .{ .bytes = try zcu.intern_pool.getOrPutString(zcu.gpa, pt.tid, elems, .maybe_embedded_nulls) },
                    } }))), true };
                },
                .pand_trunc_mem => |trunc_spec| {
                    const zcu = pt.zcu;
                    assert(spec.type.isVector(zcu) and spec.type.childType(zcu).toIntern() == .u8_type);
                    var elem_buf: [32]u8 = @splat(0);
                    const elems = elem_buf[0..spec.type.vectorLen(zcu)];
                    const from_bytes: u6 = @intCast(@divExact(trunc_spec.from.bitSize(cg.target), 8));
                    const to_bytes: u6 = @intCast(@divExact(trunc_spec.to.bitSize(cg.target), 8));
                    var index: u6 = 0;
                    while (index < elems.len) : (index += from_bytes) @memset(elems[index..][0..to_bytes], std.math.maxInt(u8));
                    return .{ try cg.tempMemFromValue(.fromInterned(try pt.intern(.{ .aggregate = .{
                        .ty = spec.type.toIntern(),
                        .storage = .{ .bytes = try zcu.intern_pool.getOrPutString(zcu.gpa, pt.tid, elems, .maybe_embedded_nulls) },
                    } }))), true };
                },
                .pand_mask_mem => |mask_spec| {
                    const zcu = pt.zcu;
                    assert(spec.type.isVector(zcu) and spec.type.childType(zcu).toIntern() == .u8_type);
                    const ref_ty = mask_spec.ref.typeOf(s);
                    assert(ref_ty.isVector(zcu));
                    var elem_buf: [64]u8 = undefined;
                    const elems = elem_buf[0..spec.type.vectorLen(zcu)];
                    const mask_len: usize = @intCast((cg.unalignedSize(ref_ty) - 1) % elems.len + 1);
                    const invert_mask: u8 = switch (mask_spec.invert) {
                        false => std.math.minInt(u8),
                        true => std.math.maxInt(u8),
                    };
                    @memset(elems[0..mask_len], ~invert_mask);
                    @memset(elems[mask_len..], invert_mask);
                    return .{ try cg.tempMemFromValue(.fromInterned(try pt.intern(.{ .aggregate = .{
                        .ty = spec.type.toIntern(),
                        .storage = .{ .bytes = try zcu.intern_pool.getOrPutString(zcu.gpa, pt.tid, elems, .maybe_embedded_nulls) },
                    } }))), true };
                },
                .ptest_mask_mem => |mask_ref| {
                    const zcu = pt.zcu;
                    assert(spec.type.isVector(zcu) and spec.type.childType(zcu).toIntern() == .u8_type);
                    const ref_ty = mask_ref.typeOf(s);
                    assert(ref_ty.isVector(zcu) and ref_ty.childType(zcu).toIntern() == .bool_type);
                    const mask_info = mask_ref.valueOf(s).register_mask.info;
                    var elem_buf: [64]u8 = @splat(0);
                    const elems = elem_buf[0..spec.type.vectorLen(zcu)];
                    const elem_bytes: u6 = @intCast(@divExact(mask_info.scalar.bitSize(cg.target), 8));
                    var index: u7 = 0;
                    for (0..@intCast(ref_ty.vectorLen(zcu))) |_| {
                        switch (mask_info.kind) {
                            .sign => {
                                @memset(elems[index..][0 .. elem_bytes - 1], std.math.minInt(u8));
                                elems[index + elem_bytes - 1] = @bitCast(@as(i8, std.math.minInt(i8)));
                            },
                            .all => @memset(elems[index..][0..elem_bytes], std.math.maxInt(u8)),
                        }
                        index += elem_bytes;
                    }
                    return .{ try cg.tempMemFromValue(.fromInterned(try pt.intern(.{ .aggregate = .{
                        .ty = spec.type.toIntern(),
                        .storage = .{ .bytes = try zcu.intern_pool.getOrPutString(zcu.gpa, pt.tid, elems, .maybe_embedded_nulls) },
                    } }))), true };
                },
                .pshufb_bswap_mem => |bswap_spec| {
                    const zcu = pt.zcu;
                    assert(spec.type.isVector(zcu) and spec.type.childType(zcu).toIntern() == .u8_type);
                    var elem_buf: [32]u8 = @splat(1 << 7);
                    const elems = elem_buf[0..spec.type.vectorLen(zcu)];
                    const len: usize = @intCast(@divExact(bswap_spec.size.bitSize(cg.target), 8));
                    var to_index: u6 = 0;
                    for (0..bswap_spec.repeat) |_| for (0..len) |from_index| {
                        @memset(elems[to_index..][0..bswap_spec.smear], @intCast(len - 1 - from_index));
                        to_index += bswap_spec.smear;
                    };
                    return .{ try cg.tempMemFromValue(.fromInterned(try pt.intern(.{ .aggregate = .{
                        .ty = spec.type.toIntern(),
                        .storage = .{ .bytes = try zcu.intern_pool.getOrPutString(zcu.gpa, pt.tid, elems, .maybe_embedded_nulls) },
                    } }))), true };
                },
                .bits_mem => |direction| {
                    const zcu = pt.zcu;
                    assert(spec.type.isVector(zcu) and spec.type.childType(zcu).toIntern() == .u8_type);
                    var bytes: [32]u8 = undefined;
                    const elems = bytes[0..spec.type.vectorLen(zcu)];
                    for (elems, 0..) |*elem, index| elem.* = switch (direction) {
                        .forward => @as(u8, 1 << 0) << @truncate(index),
                        .reverse => @as(u8, 1 << 7) >> @truncate(index),
                    };
                    return .{ try cg.tempMemFromValue(.fromInterned(try pt.intern(.{ .aggregate = .{
                        .ty = spec.type.toIntern(),
                        .storage = .{ .bytes = try zcu.intern_pool.getOrPutString(zcu.gpa, pt.tid, elems, .maybe_embedded_nulls) },
                    } }))), true };
                },
                .splat_int_mem => |splat_spec| {
                    const zcu = pt.zcu;
                    const elem_ty = spec.type.scalarType(zcu);
                    const elem_bits = cg.intInfo(elem_ty).?.bits;
                    const ref_ty = splat_spec.ref.typeOf(s);
                    assert(ref_ty.isVector(zcu) and cg.intInfo(ref_ty.childType(zcu)).?.bits <= elem_bits);
                    var elem_buf: [64]InternPool.Index = undefined;
                    const elems = elem_buf[0..if (elem_ty.toIntern() == spec.type.toIntern()) 1 else spec.type.vectorLen(zcu)];
                    const inside_len = (ref_ty.vectorLen(zcu) - 1) % elems.len + 1;
                    @memset(elems[0..inside_len], (try pt.intValue(elem_ty, @as(i64, switch (splat_spec.inside) {
                        .umin => 0,
                        .smin => std.math.minInt(i64),
                        .smax => std.math.maxInt(i64),
                    }) >> @intCast(64 - elem_bits))).toIntern());
                    @memset(elems[inside_len..], (try pt.intValue(elem_ty, @as(i64, switch (splat_spec.outside) {
                        .smin => std.math.minInt(i64),
                        .smax => std.math.maxInt(i64),
                    }) >> @intCast(64 - elem_bits))).toIntern());
                    if (elems.len == 1) return .{ try cg.tempMemFromValue(.fromInterned(elems[0])), true };
                    const mem_size = cg.unalignedSize(spec.type);
                    return .{ try cg.tempMemFromAlignedValue(
                        if (mem_size < 16) .fromByteUnits(mem_size) else .none,
                        try pt.aggregateValue(if (mem_size < 16) try pt.arrayType(.{
                            .len = elems.len,
                            .child = elem_ty.toIntern(),
                        }) else spec.type, elems),
                    ), true };
                },
                .splat_float_mem => |splat_spec| {
                    const zcu = pt.zcu;
                    assert(spec.type.isVector(zcu));
                    const elem_ty = spec.type.childType(zcu);
                    assert(cg.floatBits(elem_ty) != null);
                    const ref_ty = splat_spec.ref.typeOf(s);
                    assert(ref_ty.isVector(zcu) and ref_ty.childType(zcu).toIntern() == elem_ty.toIntern());
                    var elem_buf: [@divExact(64, 2)]InternPool.Index = undefined;
                    const elems = elem_buf[0..spec.type.vectorLen(zcu)];
                    const inside_len = (ref_ty.vectorLen(zcu) - 1) % elems.len + 1;
                    @memset(elems[0..inside_len], (try pt.floatValue(elem_ty, @as(f16, switch (splat_spec.inside) {
                        .zero => 0.0,
                    }))).toIntern());
                    @memset(elems[inside_len..], (try pt.floatValue(elem_ty, splat_spec.outside)).toIntern());
                    return .{ try cg.tempMemFromValue(try pt.aggregateValue(spec.type, elems)), true };
                },
                .frame => |frame_index| .{ try cg.tempInit(spec.type, .{ .load_frame = .{
                    .index = frame_index,
                    .off = switch (frame_index) {
                        .call_frame => switch (cg.target.cCallingConvention().?) {
                            .x86_64_sysv => 0,
                            .x86_64_win => win64_shadow_space,
                            else => unreachable,
                        },
                        else => 0,
                    },
                } }), true },
                .lazy_sym => |lazy_symbol_spec| {
                    const ip = &pt.zcu.intern_pool;
                    const ty = if (lazy_symbol_spec.ref == .none) spec.type else lazy_symbol_spec.ref.typeOf(s);
                    return .{ try cg.tempInit(.usize, .{ .lea_lazy_sym = .{
                        .kind = lazy_symbol_spec.kind,
                        .ty = switch (ip.indexToKey(ty.toIntern())) {
                            .inferred_error_set_type => |func_index| switch (ip.funcIesResolvedUnordered(func_index)) {
                                .none => unreachable,
                                else => |ty_index| ty_index,
                            },
                            else => ty.toIntern(),
                        },
                    } }), true };
                },
                .extern_func => |extern_func_spec| .{ try cg.tempInit(spec.type, .{ .lea_extern_func = try cg.addString(std.mem.span(extern_func_spec)) }), true },
            };
        }

        fn finish(spec: TempSpec, temp: *Temp, cg: *CodeGen) InnerError!void {
            switch (spec.kind) {
                else => {},
                inline .rc_mask, .mut_rc_mask, .ref_mask => |mask| temp.asMask(mask.info, cg),
            }
            cg.temp_type[@intFromEnum(temp.unwrap(cg).temp)] = spec.type;
        }
    };

