        const src2d0: Select.Operand = .{ .flags = .{ .tag = .ref, .base = .src2d }, .imm = 1 };
        const src2p0: Select.Operand = .{ .flags = .{ .tag = .ref, .base = .src2p }, .imm = 1 };
        const src2q0: Select.Operand = .{ .flags = .{ .tag = .ref, .base = .src2q }, .imm = 1 };
        const src2w1: Select.Operand = .{ .flags = .{ .tag = .ref, .base = .src2w }, .imm = 2 };
        const src2d1: Select.Operand = .{ .flags = .{ .tag = .ref, .base = .src2d }, .imm = 2 };
        const src2p1: Select.Operand = .{ .flags = .{ .tag = .ref, .base = .src2p }, .imm = 2 };
        const src2q1: Select.Operand = .{ .flags = .{ .tag = .ref, .base = .src2q }, .imm = 2 };

        fn si(imm: i32) Select.Operand {
            return .{ .flags = .{ .tag = .simm }, .imm = imm };
        }
        fn sa(base: Ref.Sized, adjust: Adjust) Select.Operand {
            return .{ .flags = .{ .tag = .simm, .adjust = adjust, .base = base } };
        }
        fn sa2(base: Ref.Sized, index: Ref, adjust: Adjust) Select.Operand {
            return .{ .flags = .{ .tag = .simm, .adjust = adjust, .base = base, .index = .{ .ref = index } } };
        }
        fn sia(imm: i32, base: Ref.Sized, adjust: Adjust) Select.Operand {
            return .{ .flags = .{ .tag = .simm, .adjust = adjust, .base = base }, .imm = imm };
        }
        fn sia2(imm: i32, base: Ref.Sized, index: Ref, adjust: Adjust) Select.Operand {
            return .{ .flags = .{ .tag = .simm, .adjust = adjust, .base = base, .index = .{ .ref = index } }, .imm = imm };
        }
        fn ui(imm: u32) Select.Operand {
            return .{ .flags = .{ .tag = .uimm }, .imm = @bitCast(imm) };
        }
        fn ua(base: Ref.Sized, adjust: Adjust) Select.Operand {
            return .{ .flags = .{ .tag = .uimm, .adjust = adjust, .base = base } };
        }
        fn uia(imm: u32, base: Ref.Sized, adjust: Adjust) Select.Operand {
            return .{ .flags = .{ .tag = .uimm, .adjust = adjust, .base = base }, .imm = @bitCast(imm) };
        }
        fn uas(base: Ref.Sized, scale: Memory.Scale, adjust: Adjust) Select.Operand {
            return .{ .flags = .{ .tag = .uimm, .adjust = adjust, .base = base, .index = .{ .scale = scale } } };
        }

        fn rm(mode: bits.RoundMode) Select.Operand {
            return .{ .flags = .{ .tag = .uimm }, .imm = @intCast(mode.imm().unsigned) };
        }
        fn sp(pred: bits.SseFloatPredicate) Select.Operand {
            return .{ .flags = .{ .tag = .uimm }, .imm = @intCast(pred.imm().unsigned) };
        }
        fn vp(pred: bits.VexFloatPredicate) Select.Operand {
            return .{ .flags = .{ .tag = .uimm }, .imm = @intCast(pred.imm().unsigned) };
        }

        fn lea(base: Ref.Sized) Select.Operand {
            return .{
                .flags = .{
                    .tag = .lea,
                    .base = base,
                },
            };
        }
        fn leaa(base: Ref.Sized, adjust: Adjust) Select.Operand {
            return .{
                .flags = .{
                    .tag = .lea,
                    .adjust = adjust,
                    .base = base,
                },
            };
        }
        fn leaad(base: Ref.Sized, adjust: Adjust, disp: i32) Select.Operand {
            return .{
                .flags = .{
                    .tag = .lea,
                    .adjust = adjust,
                    .base = base,
                },
                .imm = disp,
            };
        }
        fn lead(base: Ref.Sized, disp: i32) Select.Operand {
            return .{
                .flags = .{
                    .tag = .lea,
                    .base = base,
                },
                .imm = disp,
            };
        }
        fn leai(base: Ref.Sized, index: Ref) Select.Operand {
            return .{
                .flags = .{
                    .tag = .lea,
                    .base = base,
                    .index = .{ .ref = index },
                },
            };
        }
        fn leaia(base: Ref.Sized, index: Ref, adjust: Adjust) Select.Operand {
            return .{
                .flags = .{
                    .tag = .lea,
                    .adjust = adjust,
                    .base = base,
                    .index = .{ .ref = index },
                },
            };
        }
        fn leaiad(base: Ref.Sized, index: Ref, adjust: Adjust, disp: i32) Select.Operand {
            return .{
                .flags = .{
                    .tag = .lea,
                    .adjust = adjust,
                    .base = base,
                    .index = .{ .ref = index },
                },
                .imm = disp,
            };
        }
        fn leaid(base: Ref.Sized, index: Ref, disp: i32) Select.Operand {
            return .{
                .flags = .{
                    .tag = .lea,
                    .base = base,
                    .index = .{ .ref = index },
                },
                .imm = disp,
            };
        }
        fn leasi(base: Ref.Sized, scale: Memory.Scale, index: Ref) Select.Operand {
            return .{
                .flags = .{
                    .tag = .lea,
                    .base = base,
                    .index = .{ .ref = index, .scale = scale },
                },
            };
        }
        fn leasia(base: Ref.Sized, scale: Memory.Scale, index: Ref, adjust: Adjust) Select.Operand {
            return .{
                .flags = .{
                    .tag = .lea,
                    .adjust = adjust,
                    .base = base,
                    .index = .{ .ref = index, .scale = scale },
                },
            };
        }
        fn leasid(base: Ref.Sized, scale: Memory.Scale, index: Ref, disp: i32) Select.Operand {
            return .{
                .flags = .{
                    .tag = .lea,
                    .base = base,
                    .index = .{ .ref = index, .scale = scale },
                },
                .imm = disp,
            };
        }
        fn leasiad(base: Ref.Sized, scale: Memory.Scale, index: Ref, adjust: Adjust, disp: i32) Select.Operand {
            return .{
                .flags = .{
                    .tag = .lea,
                    .adjust = adjust,
                    .base = base,
                    .index = .{ .ref = index, .scale = scale },
                },
                .imm = disp,
            };
        }

        fn mem(base: Ref.Sized) Select.Operand {
            return .{
                .flags = .{
                    .tag = .mem,
                    .base = base,
                },
            };
        }
        fn memd(base: Ref.Sized, disp: i32) Select.Operand {
            return .{
                .flags = .{
                    .tag = .mem,
                    .base = base,
                },
                .imm = disp,
            };
        }
        fn mema(base: Ref.Sized, adjust: Adjust) Select.Operand {
            return .{
                .flags = .{
                    .tag = .mem,
                    .adjust = adjust,
                    .base = base,
                },
            };
        }
        fn memad(base: Ref.Sized, adjust: Adjust, disp: i32) Select.Operand {
            return .{
                .flags = .{
                    .tag = .mem,
                    .adjust = adjust,
                    .base = base,
                },
                .imm = disp,
            };
        }
        fn memi(base: Ref.Sized, index: Ref) Select.Operand {
            return .{
                .flags = .{
                    .tag = .mem,
                    .base = base,
                    .index = .{ .ref = index },
                },
            };
        }
        fn memia(base: Ref.Sized, index: Ref, adjust: Adjust) Select.Operand {
            return .{
                .flags = .{
                    .tag = .mem,
                    .adjust = adjust,
                    .base = base,
                    .index = .{ .ref = index },
                },
            };
        }
        fn memiad(base: Ref.Sized, index: Ref, adjust: Adjust, disp: i32) Select.Operand {
            return .{
                .flags = .{
                    .tag = .mem,
                    .adjust = adjust,
                    .base = base,
                    .index = .{ .ref = index },
                },
                .imm = disp,
            };
        }
        fn memid(base: Ref.Sized, index: Ref, disp: i32) Select.Operand {
            return .{
                .flags = .{
                    .tag = .mem,
                    .base = base,
                    .index = .{ .ref = index },
                },
                .imm = disp,
            };
        }
        fn memsi(base: Ref.Sized, scale: Memory.Scale, index: Ref) Select.Operand {
            return .{
                .flags = .{
                    .tag = .mem,
                    .base = base,
                    .index = .{ .ref = index, .scale = scale },
                },
            };
        }
        fn memsia(base: Ref.Sized, scale: Memory.Scale, index: Ref, adjust: Adjust) Select.Operand {
            return .{
                .flags = .{
                    .tag = .mem,
                    .adjust = adjust,
                    .base = base,
                    .index = .{ .ref = index, .scale = scale },
                },
            };
        }
        fn memsid(base: Ref.Sized, scale: Memory.Scale, index: Ref, disp: i32) Select.Operand {
            return .{
                .flags = .{
                    .tag = .mem,
                    .base = base,
                    .index = .{ .ref = index, .scale = scale },
                },
                .imm = disp,
            };
        }
        fn memsiad(base: Ref.Sized, scale: Memory.Scale, index: Ref, adjust: Adjust, disp: i32) Select.Operand {
            return .{
                .flags = .{
                    .tag = .mem,
                    .adjust = adjust,
                    .base = base,
                    .index = .{ .ref = index, .scale = scale },
                },
                .imm = disp,
            };
        }

        fn adjustedImm(op: Select.Operand, comptime SignedImm: type, s: *const Select) SignedImm {
            const UnsignedImm = @Int(.unsigned, @typeInfo(SignedImm).int.bits);
            const lhs: SignedImm = lhs: switch (op.flags.adjust.lhs) {
                .none => 0,
                .ptr_size => @divExact(s.cg.target.ptrBitWidth(), 8),
                .ptr_bit_size => s.cg.target.ptrBitWidth(),
                .size => @intCast(op.flags.base.ref.typeOf(s).abiSize(s.cg.pt.zcu)),
                .src0_size => @intCast(Select.Operand.Ref.src0.typeOf(s).abiSize(s.cg.pt.zcu)),
                .dst0_size => @intCast(Select.Operand.Ref.dst0.typeOf(s).abiSize(s.cg.pt.zcu)),
                .delta_size => @intCast(@as(SignedImm, @intCast(op.flags.base.ref.typeOf(s).abiSize(s.cg.pt.zcu))) -
                    @as(SignedImm, @intCast(op.flags.index.ref.typeOf(s).abiSize(s.cg.pt.zcu)))),
                .delta_elem_size => @intCast(@as(SignedImm, @intCast(op.flags.base.ref.typeOf(s).elemType2(s.cg.pt.zcu).abiSize(s.cg.pt.zcu))) -
                    @as(SignedImm, @intCast(op.flags.index.ref.typeOf(s).elemType2(s.cg.pt.zcu).abiSize(s.cg.pt.zcu)))),
                .unaligned_size => @intCast(s.cg.unalignedSize(op.flags.base.ref.typeOf(s))),
                .unaligned_size_add_elem_size => {
                    const ty = op.flags.base.ref.typeOf(s);
                    break :lhs @intCast(s.cg.unalignedSize(ty) + ty.elemType2(s.cg.pt.zcu).abiSize(s.cg.pt.zcu));
                },
                .unaligned_size_sub_elem_size => {
                    const ty = op.flags.base.ref.typeOf(s);
                    break :lhs @intCast(s.cg.unalignedSize(ty) - ty.elemType2(s.cg.pt.zcu).abiSize(s.cg.pt.zcu));
                },
                .unaligned_size_sub_2_elem_size => {
                    const ty = op.flags.base.ref.typeOf(s);
                    break :lhs @intCast(s.cg.unalignedSize(ty) - ty.elemType2(s.cg.pt.zcu).abiSize(s.cg.pt.zcu) * 2);
                },
                .bit_size => @intCast(s.cg.nonBoolScalarBitSize(op.flags.base.ref.typeOf(s))),
                .src0_bit_size => @intCast(s.cg.nonBoolScalarBitSize(Select.Operand.Ref.src0.typeOf(s))),
                .@"8_size_sub_bit_size" => {
                    const ty = op.flags.base.ref.typeOf(s);
                    break :lhs @intCast(8 * ty.abiSize(s.cg.pt.zcu) - ty.bitSize(s.cg.pt.zcu));
                },
                .len => @intCast(op.flags.base.ref.typeOf(s).vectorLen(s.cg.pt.zcu)),
                .elem_limbs => @intCast(@divExact(
                    op.flags.base.ref.typeOf(s).scalarType(s.cg.pt.zcu).abiSize(s.cg.pt.zcu),
                    @divExact(op.flags.base.size.bitSize(s.cg.target), 8),
                )),
                .elem_size => @intCast(op.flags.base.ref.typeOf(s).elemType2(s.cg.pt.zcu).abiSize(s.cg.pt.zcu)),
                .src0_elem_size => @intCast(Select.Operand.Ref.src0.typeOf(s).elemType2(s.cg.pt.zcu).abiSize(s.cg.pt.zcu)),
                .dst0_elem_size => @intCast(Select.Operand.Ref.dst0.typeOf(s).elemType2(s.cg.pt.zcu).abiSize(s.cg.pt.zcu)),
                .src0_elem_size_mul_src1 => @intCast(Select.Operand.Ref.src0.typeOf(s).elemType2(s.cg.pt.zcu).abiSize(s.cg.pt.zcu) *
                    Select.Operand.Ref.src1.valueOf(s).immediate),
                .vector_index => switch (op.flags.base.ref.typeOf(s).ptrInfo(s.cg.pt.zcu).flags.vector_index) {
                    .none => unreachable,
                    else => |vector_index| @intFromEnum(vector_index),
                },
                .src1 => @intCast(Select.Operand.Ref.src1.valueOf(s).immediate),
                .src1_sub_bit_size => @as(SignedImm, @intCast(Select.Operand.Ref.src1.valueOf(s).immediate)) -
                    @as(SignedImm, @intCast(s.cg.nonBoolScalarBitSize(op.flags.base.ref.typeOf(s)))),
                .log2_src0_elem_size => @intCast(std.math.log2(Select.Operand.Ref.src0.typeOf(s).elemType2(s.cg.pt.zcu).abiSize(s.cg.pt.zcu))),
                .elem_mask => @as(u8, std.math.maxInt(u8)) >> @intCast(
                    8 - ((s.cg.unalignedSize(op.flags.base.ref.typeOf(s)) - 1) %
                        @divExact(op.flags.base.size.bitSize(s.cg.target), 8) + 1 >>
                        op.flags.index.scale.toLog2()),
                ),
                inline .smin, .smax, .umax, .smin_shr_src1, .smax_shr_src1, .umax_shr_src1 => |adjust| switch (op.flags.base.size) {
                    else => unreachable,
                    inline .none, .byte, .word, .dword, .qword => |size| {
                        const Imm = switch (adjust) {
                            else => comptime unreachable,
                            .smin, .smax, .smin_shr_src1, .smax_shr_src1 => SignedImm,
                            .umax, .umax_shr_src1 => UnsignedImm,
                        };
                        const RefImm = switch (size) {
                            else => comptime unreachable,
                            .none => Imm,
                            .byte, .word, .dword, .qword => @Int(
                                @typeInfo(Imm).int.signedness,
                                size.bitSize(undefined),
                            ),
                        };
                        break :lhs @bitCast(@as(Imm, @intCast(@as(RefImm, switch (adjust) {
                            else => comptime unreachable,
                            .smin, .smin_shr_src1 => std.math.minInt,
                            .smax, .umax, .smax_shr_src1, .umax_shr_src1 => std.math.maxInt,
                        }(RefImm)) >> @truncate(switch (adjust) {
                            else => comptime unreachable,
                            .smin, .smax, .umax => 0,
                            .smin_shr_src1, .smax_shr_src1, .umax_shr_src1 => Select.Operand.Ref.src1.valueOf(s).immediate,
                        } -% s.cg.nonBoolScalarBitSize(op.flags.base.ref.typeOf(s))))));
                    },
                },
                .repeat => switch (SignedImm) {
                    else => unreachable,
                    i64 => return @as(i64, op.imm) << 32 | @as(u32, @bitCast(op.imm)),
                },
            };
            const rhs = op.flags.adjust.rhs.toLog2();
            const op_res = op_res: switch (op.flags.adjust.op) {
                .mul => {
                    const op_res = @shlWithOverflow(lhs, rhs);
                    assert(op_res[1] == 0);
                    break :op_res op_res[0];
                },
                .div => @shrExact(lhs, rhs),
                .div_8_down => lhs >> 3 & @as(SignedImm, -1) << rhs,
                .rem_8_mul => lhs & ((@as(SignedImm, 8) << rhs) - 1),
                .up_2_mul => ((lhs - 1) & @as(SignedImm, -2) << rhs) + (@as(SignedImm, 2) << rhs),
                .up_32_mul => ((lhs - 1) & @as(SignedImm, -32) << rhs) + (@as(SignedImm, 32) << rhs),
            };
            const disp: SignedImm = @bitCast(@as(UnsignedImm, @as(u32, @bitCast(op.imm))));
            return switch (op.flags.adjust.sign) {
                .neg => disp - op_res,
                .pos => disp + op_res,
            };
        }

        fn lower(op: Select.Operand, s: *Select) InnerError!CodeGen.Operand {
            return switch (op.flags.tag) {
                .none => .none,
                .label => if (op.imm < 0)
                    .{ .inst = s.labels[@intCast(~op.imm)].backward.? }
                else for (&s.labels[@intCast(op.imm)].forward) |*label| {
                    if (label.*) |_| continue;
                    label.* = @intCast(s.cg.mir_instructions.len);
                    break .{ .inst = undefined };
                } else unreachable,
                .ref => switch (op.imm) {
                    else => unreachable,
                    0 => switch (op.flags.base.ref.valueOf(s)) {
                        .none, .unreach, .dead, .undef => unreachable,
                        .immediate => |imm| .{ .imm = switch (op.flags.base.size) {
                            .byte => if (std.math.cast(i8, @as(i64, @bitCast(imm)))) |simm| .s(simm) else .u(@as(u8, @intCast(imm))),
                            .word => if (std.math.cast(i16, @as(i64, @bitCast(imm)))) |simm| .s(simm) else .u(@as(u16, @intCast(imm))),
                            .dword => if (std.math.cast(i32, @as(i64, @bitCast(imm)))) |simm| .s(simm) else .u(@as(u32, @intCast(imm))),
                            .qword => if (std.math.cast(i32, @as(i64, @bitCast(imm)))) |simm| .s(simm) else .u(imm),
                            else => unreachable,
                        } },
                        .eflags => unreachable,
                        .register => |reg| .{ .reg = s.lowerReg(reg.toSize(op.flags.base.size, s.cg.target)) },
                        .register_pair, .register_triple, .register_quadruple, .register_offset, .register_overflow => unreachable,
                        .register_mask => |reg_mask| .{ .reg = s.lowerReg(reg_mask.reg.toSize(op.flags.base.size, s.cg.target)) },
                        .lea_nav => |nav| .{ .imm = .{ .nav = .{ .index = nav } } },
                        .lea_uav => |uav| .{ .imm = .{ .uav = uav } },
                        .lea_lazy_sym => |lazy_sym| .{ .imm = .{ .lazy_sym = lazy_sym } },
                        .lea_extern_func => |extern_func| .{ .imm = .{ .extern_func = extern_func } },
                        else => |mcv| .{ .mem = try mcv.mem(s.cg, .{ .size = op.flags.base.size }) },
                        .lea_frame, .elementwise_args, .reserved_frame, .air_ref => unreachable,
                    },
                    1...2 => |imm| switch (op.flags.base.ref.valueOf(s)) {
                        inline .register_pair, .register_triple, .register_quadruple => |regs| .{
                            .reg = s.lowerReg(regs[@intCast(imm - 1)].toSize(op.flags.base.size, s.cg.target)),
                        },
                        else => |mcv| .{ .mem = try mcv.mem(s.cg, .{
                            .size = op.flags.base.size,
                            .disp = @as(i32, @intCast(@divExact(op.flags.base.size.bitSize(s.cg.target), 8))) * (imm - 1),
                        }) },
                    },
                },
                .simm => .{ .imm = .s(op.adjustedImm(i32, s)) },
                .uimm => .{ .imm = .u(@bitCast(op.adjustedImm(i64, s))) },
                .lea => .{ .mem = try op.flags.base.ref.valueOf(s).deref().mem(s.cg, .{
                    .size = op.flags.base.size,
                    .index = switch (op.flags.index.ref.valueOf(s)) {
                        else => unreachable,
                        .none => .none,
                        .register => |index_reg| index_reg.toSize(.ptr, s.cg.target),
                    },
                    .scale = op.flags.index.scale,
                    .disp = op.adjustedImm(i32, s) + switch (op.flags.index.ref.valueOf(s)) {
                        else => unreachable,
                        .none, .register, .lea_nav, .lea_uav, .lea_lazy_sym, .lea_extern_func => 0,
                        .register_offset => |base_reg_off| base_reg_off.off,
                    },
                }) },
                .mem => .{ .mem = try op.flags.base.ref.valueOf(s).mem(s.cg, .{
                    .size = op.flags.base.size,
                    .index = switch (op.flags.index.ref.valueOf(s)) {
                        else => unreachable,
                        .none => .none,
                        .register => |index_reg| index_reg.toSize(.ptr, s.cg.target),
                    },
                    .scale = op.flags.index.scale,
                    .disp = op.adjustedImm(i32, s),
                }) },
            };
        }
    };
};
fn select(
    cg: *CodeGen,
    dst_temps: []Temp,
    dst_tys: []const Type,
    src_temps: []Temp,
    cases: []const Select.Case,
) Select.Error!void {
    @setEvalBranchQuota(33_500);
    cases: for (cases) |case| {
        switch (case.required_abi) {
            .any => {},
            .gnu => if (switch (cg.target.abi) {
                .none, .msvc, .itanium => cg.target.os.tag == .windows,
                else => false,
            }) continue :cases,
            .msvc => if (switch (cg.target.abi) {
                .none, .msvc, .itanium => cg.target.os.tag != .windows,
                else => true,
            }) continue :cases,
        }
        switch (case.required_cc_abi) {
            .any => {},
            .sysv64 => if (cg.target.cCallingConvention().? != .x86_64_sysv) continue :cases,
            .win64 => if (cg.target.cCallingConvention().? != .x86_64_win) continue :cases,
        }
        for (case.required_features) |required_feature| if (required_feature) |feature| if (!cg.hasFeature(feature)) continue :cases;
        for (case.src_constraints[0..src_temps.len], src_temps) |src_constraint, src_temp| if (!src_constraint.accepts(src_temp.typeOf(cg), cg)) continue :cases;
        for (case.dst_constraints[0..dst_temps.len], dst_tys) |dst_constraint, dst_ty| if (!dst_constraint.accepts(dst_ty, cg)) continue :cases;
        if (std.debug.runtime_safety) {
            for (case.src_constraints[src_temps.len..]) |src_constraint| assert(src_constraint == .any);
            for (case.dst_constraints[dst_temps.len..]) |dst_constraint| assert(dst_constraint == .any);
            for (case.dst_temps[dst_temps.len..]) |dst_temp| assert(dst_temp == .unused);
        }
        patterns: for (case.patterns) |pattern| {
            for (pattern.src[0..src_temps.len], src_temps) |src_pattern, src_temp| if (!src_pattern.matches(src_temp, cg)) continue :patterns;
            if (std.debug.runtime_safety) for (pattern.src[src_temps.len..]) |src_pattern| assert(src_pattern == .none);

            if (case.call_frame.alignment != .none) {
                const frame_allocs_slice = cg.frame_allocs.slice();
                const stack_frame_size =
                    &frame_allocs_slice.items(.abi_size)[@intFromEnum(FrameIndex.call_frame)];
                stack_frame_size.* = @max(stack_frame_size.*, switch (cg.target.cCallingConvention().?) {
                    .x86_64_sysv => case.call_frame.size,
                    .x86_64_win => win64_shadow_space + case.call_frame.size,
                    else => unreachable,
                });
                const stack_frame_align =
                    &frame_allocs_slice.items(.abi_align)[@intFromEnum(FrameIndex.call_frame)];
                stack_frame_align.* = stack_frame_align.max(case.call_frame.alignment);
            }

            var s: Select = .{
                .cg = cg,
                .temps = undefined,
                .types = undefined,
                .labels = @splat(.{ .forward = @splat(null), .backward = null }),
                .top = 0,
            };
            const s_tmp_types = s.types[@intFromEnum(Select.Operand.Ref.tmp0)..@intFromEnum(Select.Operand.Ref.dst0)];
            const s_tmp_temps = s.temps[@intFromEnum(Select.Operand.Ref.tmp0)..@intFromEnum(Select.Operand.Ref.dst0)];
            const s_dst_types = s.types[@intFromEnum(Select.Operand.Ref.dst0)..@intFromEnum(Select.Operand.Ref.src0)];
            const s_dst_temps = s.temps[@intFromEnum(Select.Operand.Ref.dst0)..@intFromEnum(Select.Operand.Ref.src0)];
            const s_src_types = s.types[@intFromEnum(Select.Operand.Ref.src0)..@intFromEnum(Select.Operand.Ref.none)];
            const s_src_temps = s.temps[@intFromEnum(Select.Operand.Ref.src0)..@intFromEnum(Select.Operand.Ref.none)];

            for (s_tmp_types, case.extra_temps) |*ty, spec| ty.* = spec.type;
            @memcpy(s_dst_types[0..dst_tys.len], dst_tys);
            for (s_src_types[0..src_temps.len], src_temps) |*ty, temp| ty.* = temp.typeOf(cg);
            std.mem.swap(Type, &s_src_types[pattern.commute[0]], &s_src_types[pattern.commute[1]]);

            caller_preserved: {
                const cc = switch (case.clobbers.caller_preserved) {
                    .none => break :caller_preserved,
                    .ccc => cg.target.cCallingConvention().?,
                    .zigcc => .auto,
                };
                assert(case.clobbers.eflags);
                const err_ret_trace_reg = if (cc == .auto and cg.pt.zcu.comp.config.any_error_tracing) err_ret_trace_reg: {
                    const param_gpr = abi.getCAbiIntParamRegs(.auto);
                    break :err_ret_trace_reg param_gpr[param_gpr.len - 1];
                } else .none;
                switch (cc) {
                    else => unreachable,
                    inline .x86_64_sysv, .x86_64_win, .auto => |_, tag| inline for (comptime abi.getCallerPreservedRegs(tag)) |reg| skip: {
                        if (reg == err_ret_trace_reg) break :skip;
                        const tracked_index = RegisterManager.indexOfKnownRegIntoTracked(reg) orelse break :skip;
                        try cg.register_manager.getRegIndex(tracked_index, null);
                        assert(cg.register_manager.lockRegIndexAssumeUnused(tracked_index).tracked_index == tracked_index);
                    },
                }
            }

            @memcpy(s_src_temps[0..src_temps.len], src_temps);
            std.mem.swap(Temp, &s_src_temps[pattern.commute[0]], &s_src_temps[pattern.commute[1]]);
            var dst_locks: [s_dst_temps.len][2]?RegisterLock = @splat(@splat(null));
            for (dst_locks[0..dst_temps.len], case.dst_temps[0..dst_temps.len]) |*dst_lock, dst_kind| dst_lock.* = try dst_kind.lock(cg);
            var tmp_locks: [s_tmp_temps.len][2]?RegisterLock = @splat(@splat(null));
            for (&tmp_locks, case.extra_temps) |*tmp_lock, tmp_spec| tmp_lock.* = try tmp_spec.kind.lock(cg);

            while (true) for (pattern.src[0..src_temps.len], src_temps) |src_pattern, *src_temp| {
                if (try src_pattern.convert(src_temp, cg)) break;
            } else break;
            var src_locks: [s_src_temps.len][2]?RegisterLock = @splat(@splat(null));
            for (src_locks[0..src_temps.len], src_temps) |*locks, src_temp| {
                const regs: [2]Register = switch (src_temp.tracking(cg).short) {
                    else => continue,
                    .register => |reg| .{ reg, .none },
                    .register_pair => |regs| regs,
                };
                for (regs, locks) |reg, *lock| {
                    if (reg == .none) continue;
                    lock.* = cg.register_manager.lockRegIndex(RegisterManager.indexOfRegIntoTracked(reg) orelse continue);
                }
            }
            @memcpy(s_src_temps[0..src_temps.len], src_temps);
            std.mem.swap(Temp, &s_src_temps[pattern.commute[0]], &s_src_temps[pattern.commute[1]]);

            if (case.clobbers.eflags) try cg.spillEflagsIfOccupied();

            var tmp_owned: [s_tmp_temps.len]bool = @splat(false);
            for (s_tmp_temps, &tmp_owned, case.extra_temps) |*temp, *owned, tmp_spec| temp.*, owned.* = try tmp_spec.create(&s);
            for (dst_temps, dst_tys, case.dst_temps[0..dst_temps.len]) |*dst_temp, dst_ty, tmp_kind| dst_temp.*, _ = try Select.TempSpec.create(.{ .type = dst_ty, .kind = tmp_kind }, &s);
            @memcpy(s_dst_temps[0..dst_temps.len], dst_temps);

            switch (case.each) {
                .once => |body| {
                    for (body) |inst| try s.emit(inst);
                    s.emitLabel(.@"0:");
                },
            }
            assert(s.top == 0);

            for (src_locks) |locks| for (locks) |lock| if (lock) |reg| cg.register_manager.unlockReg(reg);
            for (tmp_locks) |locks| for (locks) |lock| if (lock) |reg| cg.register_manager.unlockReg(reg);
            for (dst_locks) |locks| for (locks) |lock| if (lock) |reg| cg.register_manager.unlockReg(reg);
            caller_preserved: {
                const cc = switch (case.clobbers.caller_preserved) {
                    .none => break :caller_preserved,
                    .ccc => cg.target.cCallingConvention().?,
                    .zigcc => .auto,
                };
                const err_ret_trace_reg = if (cc == .auto and cg.pt.zcu.comp.config.any_error_tracing) err_ret_trace_reg: {
                    const param_gpr = abi.getCAbiIntParamRegs(.auto);
                    break :err_ret_trace_reg param_gpr[param_gpr.len - 1];
                } else .none;
                switch (cc) {
                    else => unreachable,
                    inline .x86_64_sysv, .x86_64_win, .auto => |_, tag| inline for (comptime abi.getCallerPreservedRegs(tag)) |reg| skip: {
                        if (reg == err_ret_trace_reg) break :skip;
                        cg.register_manager.unlockReg(.{ .tracked_index = RegisterManager.indexOfKnownRegIntoTracked(reg) orelse break :skip });
                    },
                }
            }
            for (tmp_owned, s_tmp_temps) |owned, temp| if (owned) try temp.die(cg);
            for (dst_tys, case.dst_temps[0..dst_temps.len], dst_temps) |dst_ty, dst_kind, *dst_temp| try Select.TempSpec.finish(.{ .type = dst_ty, .kind = dst_kind }, dst_temp, cg);
            return;
        }
    }
    return error.SelectFailed;
}
